def _append_reason(reasons: list[str], reason: str) -> None: if reason not in reasons: reasons.append(reason)
def _non_empty(value: object) -> bool: return isinstance(value, str) and bool(value.strip())
def _all_non_empty(values: tuple[str, ...]) -> bool: return bool(values) and all(_non_empty(value) for value in values)
def _is_subset(child: tuple[str, ...], parent: tuple[str, ...]) -> bool: return set(child).issubset(set(parent))
def _includes(parent_forbidden: tuple[str, ...], child_forbidden: tuple[str, ...]) -> bool: return set(parent_forbidden).issubset(set(child_forbidden))
def _tuple_add_unique(values: tuple[str, ...], value: str) -> tuple[str, ...]: if value in values: return values return (*values, value)
def _source_creator_reason(created_by: str) -> str | None: creator = created_by.lower() if "human" in creator: return REASON_HUMAN_APPROVAL_IS_EVIDENCE_ONLY if "llm" in creator or "gemini" in creator or "model" in creator: return REASON_LLM_CANNOT_CREATE_ACTION_COMMIT_PACKET if "avf" in creator: return REASON_AVF_CANNOT_CREATE_ACTION_COMMIT_PACKET if "drs" in creator: return REASON_DRS_CANNOT_CREATE_ACTION_COMMIT_PACKET if "gt" in creator or "lgt" in creator: return REASON_GT_LGT_CANNOT_CREATE_ACTION_COMMIT_PACKET return None
