import hashlib
import json

VERSION = 'ews.photo.v01'
MIXED_VERSION = 'ews.mixed.v01'
CLASSES = ('MediaSourceNeedle', 'RenderEngineNeedle', 'DisplayGatewayNeedle',
           'ControlSurfaceNeedle', 'AudioSinkNeedle', 'SidecarWriteNeedle')
