    try{await api('/audio-loss',{});await refresh();$('result').textContent='Audio continuation completed. '+state.media.status;}
    catch(e){failClosed(e);await refresh().catch(()=>{});$('result').textContent=e.message;}
    finally{busy=false;audioBusy=false;syncControls();}
};
syncControls();hideControls();poll=setInterval(()=>{if(!busy&&!refreshing&&!stopped)refresh().catch(()=>{});},1000);
addEventListener('pagehide',()=>{stopped=true;generation++;clearInterval(poll);});refresh().catch(()=>{});
</script></body></html>'''


class Viewer:
    def __init__(self,workspace):
        self.workspace=workspace
        self.owner_token,self.control_token=(secrets.token_urlsafe(32) for _ in range(2))
        self.sequence=0
        self.servers=[]
        self.threads=[]
        for role in ('control','owner'):
            server=ThreadingHTTPServer(('127.0.0.1',0),self.handler(role))
            self.servers.append(server)
        self.control_url='http://127.0.0.1:'+str(self.servers[0].server_port)
        self.owner_url='http://127.0.0.1:'+str(self.servers[1].server_port)
        for server in self.servers:
            thread=threading.Thread(target=server.serve_forever,kwargs={'poll_interval':0.1},daemon=True)
            thread.start()
            self.threads.append(thread)

    def handler(self,role):
        viewer=self
        token=self.owner_token if role=='owner' else self.control_token
        class Handler(BaseHTTPRequestHandler):
            def log_message(self,*args):
                pass

            def answer(self,code,value,kind='application/json'):
                body=value if type(value) is bytes else c.canonical(value)
                self.send_response(code)
                self.send_header('Content-Type',kind)
                self.send_header('Cache-Control','no-store')
                self.send_header('X-Content-Type-Options','nosniff')
                self.send_header('Referrer-Policy','no-referrer')
                self.send_header('Content-Security-Policy',"default-src 'self'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src 'self' blob:; frame-src http://127.0.0.1:*; connect-src 'self'; base-uri 'none'; form-action 'none'")
                self.send_header('Content-Length',str(len(body)))
                self.end_headers()
                self.wfile.write(body)

            def check(self,auth=True):
                origin=f'http://127.0.0.1:{self.server.server_port}'
                c.require(self.headers.get('Host')==origin[7:],'http_host')
                c.require(self.headers.get('Origin') in (None,origin),'http_origin')
                if auth:
                    c.require(self.headers.get('Authorization')=='Bearer '+token,'http_role_credential')

            def do_GET(self):
                try:
                    self.check(self.path!='/')
                    if self.path=='/':
                        label={'CONTROLLED_DETERMINISTIC':'Controlled','LIVE':'Live','CAPTURED_REEXECUTION':'Captured',
                            'DRS_REUSE_CANDIDATE':'DRS reuse candidate'}[viewer.workspace.mode]
                        html=(OWNER_HTML if role=='owner' else CONTROL_HTML).replace('STYLE',STYLE).replace('MODE',label)
                        return self.answer(200,html.encode(),'text/html; charset=utf-8')
                    if self.path=='/state':
                        with viewer.workspace.lock:
                            return self.answer(200,dict(viewer.workspace.state(),control_sequence=viewer.sequence))
                    if role=='owner' and self.path=='/control-link':
                        return self.answer(200,dict(url=viewer.control_url+'/#'+viewer.control_token))
                    if role=='control' and self.path.startswith('/frame/'):
                        from urllib.parse import unquote
                        with viewer.workspace.lock:
                            ref=unquote(self.path[len('/frame/'):])
                            viewer.workspace.validate_frame(ref)
                            return self.answer(200,viewer.workspace.photo_frame(ref),'image/png')
                    if role=='control' and self.path.startswith('/media-frame/'):
                        from urllib.parse import unquote
                        with viewer.workspace.lock:
                            return self.answer(200,viewer.workspace.media_frame(unquote(self.path[len('/media-frame/'):])),'image/png')
                    raise ValueError('endpoint_not_allowed')
                except (ValueError,KeyError) as exc:
                    self.answer(403,dict(error=str(exc)))
                except OSError:
                    self.answer(403,dict(error='preview_unavailable'))

            def do_POST(self):
                try:
                    self.check()
                    length=int(self.headers.get('Content-Length','0'))
                    c.require(0<length<=16384,'http_payload_size')
                    value=parse(self.rfile.read(length))
                    with viewer.workspace.lock:
                        if role=='control' and self.path=='/command':
                            c.exact(value,('version','session','sequence','command'))
                            c.require(type(value['version']) is int and value['version']==1 and type(value['sequence']) is int and value['sequence']==viewer.sequence+1
                                and value['session']==viewer.workspace.id,'control_sequence_session')
                            c.require(value['command']['op'] not in ('OPEN','SAVE','END'),'control_cannot_approve')
                            c.command(value['command'],viewer.workspace.allowed)
                            viewer.sequence+=1
                            result=viewer.workspace.command(value['command']['op'],value['command']['value'])
                        elif role=='owner' and self.path=='/approve':
                            c.exact(value,('candidate',))
                            approval=viewer.workspace.approve(value['candidate'],actor='MANUAL_OWNER_CONFIRMATION')
                            result=viewer.workspace.command('SAVE',approval)
                        elif role=='owner' and self.path=='/end':
                            c.exact(value,())
                            result=viewer.workspace.close('OWNER_END')
                        elif role=='owner' and self.path=='/audio-loss':
                            c.exact(value,())
                            result=viewer.workspace.withdraw_audio()
                        else:
                            raise ValueError('endpoint_not_allowed')
                    self.answer(200,result)
                except (ValueError,KeyError,TypeError) as exc:
                    self.answer(403,dict(error=str(exc)))
                except OSError:
                    self.answer(403,dict(error='workspace_io_unavailable'))
        return Handler

    def close(self):
        for server in self.servers:
            server.shutdown()
            server.server_close()
        for thread in self.threads:
            thread.join()

"""Five missing EWS boundaries; tiny fixtures, production validators/handlers.
Loopback handlers run in this test process so file-sink counters observe the executing handler threads. This is not a subprocess sandbox or a Workspace run. """ import base64 import contextlib import copy import hashlib import http.client import io import json import os from pathlib import Path import threading import time
from PIL import Image import pytest
from hedgehog.domains.ephemeral_workspace import contracts_v01 as c from hedgehog.domains.ephemeral_workspace import local_services_v01 as services from hedgehog.domains.ephemeral_workspace import semantic_roles_v01 as roles from hedgehog.domains.ephemeral_workspace import media_v01 as media from hedgehog.domains.ephemeral_workspace import semantic_adapter_v01 as semantic from hedgehog.domains.ephemeral_workspace import kernel_adapter_v01 as kernel
def _sha(data): return hashlib.sha256(data).hexdigest() def _write(path, value): path.write_text(json.dumps(value, indent=2, sort_keys=True, ensure_ascii=True) + "\n")
@pytest.fixture def evidence(request): directory = Path(os.environ["EWS4R_PROBE_EVIDENCE"]) directory.mkdir(parents=True, exist_ok=True) def record(requirement, result): sources = [] candidate = Path(__file__).resolve().parents[1] for label, path in [("test", Path(__file__)), *[(m.__name__, Path(m.__file__)) for m in (c, services, roles, media, semantic, kernel)]]: path = path.resolve() assert path.is_relative_to(candidate) data = path.read_bytes() sources.append({"module": label, "path": path.relative_to(candidate).as_posix(), "sha256": _sha(data), "bytes": len(data)}) result.update(version="ews4r.local_boundary_probe.v01", requirement=requirement, nodeid=request.node.nodeid, source_pins=sources, principal_run_counters_modified=False, fixture_root_decisions=0, workspace_instances=0, D_executions=0, E_executions=0, provider_calls=0, external_network_calls=0, subprocesses=0) _write(directory / (requirement + ".json"), result) return record
def _image(): stream = io.BytesIO() Image.new("RGB", (8, 8), (25, 90, 145)).save(stream, format="PNG") return stream.getvalue()
@contextlib.contextmanager def _service(role, tmp_path, monkeypatch, asset_id="asset:1"): source = tmp_path / "fixture_source.png" source.write_bytes(_image()) original = source.read_bytes() started = time.monotonic() initial_threads = set(threading.enumerate()) config = dict(role=role, session="fixture:local_probe", deadline=started + 60, token="fixture_rpc_credential", read_token="fixture_read_credential", nonce="fixture_birth_marker", parent_pid=os.getppid(), minimize="preview_without_metadata", preview="fit", assets={asset_id: [str(source), _sha(original)]}, pcm_chunks=[]) servers, errors, births = [], [], [] ready = threading.Event() owner_thread = threading.get_ident() counts = {"source_read_attempts": 0, "source_write_attempts": 0, "render_dispatches": 0} originals = (io.open, open, os.open, services.render, services.ThreadingHTTPServer)
def path_is_source(value): return isinstance(value, (str, bytes, os.PathLike)) and Path(os.fsdecode(value)).absolute() == source.absolute()
def observed_open(original_open): def call(file, mode="r", *args, **kwargs): if threading.get_ident() != owner_thread and path_is_source(file): counts["source_write_attempts" if any(x in str(mode) for x in "wax+") else "source_read_attempts"] += 1 return original_open(file, mode, *args, **kwargs) return call
def observed_os_open(file, flags, *args, **kwargs): if threading.get_ident() != owner_thread and path_is_source(file): writing = flags & (os.O_WRONLY | os.O_RDWR | os.O_CREAT | os.O_TRUNC | os.O_APPEND) counts["source_write_attempts" if writing else "source_read_attempts"] += 1 return originals[2](file, flags, *args, **kwargs)
def observed_render(*args, **kwargs): counts["render_dispatches"] += 1 return originals[3](*args, **kwargs)
def server_factory(*args, **kwargs): server = originals[4](*args, **kwargs) servers.append(server) ready.set() return server
def observe_birth(value, **kwargs): birth = json.loads(value) births.append({"same_process": birth["pid"] == os.getpid(), "role_matches": birth["role"] == role, "birth_matches": birth["nonce"] == config["nonce"]})
def run(): try: services.worker(config) except BaseException as error: errors.append(type(error).__name__) ready.set()
with monkeypatch.context() as patch: patch.setattr(io, "open", observed_open(originals[0])) patch.setattr("builtins.open", observed_open(originals[1])) patch.setattr(os, "open", observed_os_open) patch.setattr(services, "render", observed_render) patch.setattr(services, "ThreadingHTTPServer", server_factory) patch.setattr(services, "print", observe_birth, raising=False) thread = threading.Thread(target=run, name="ews4r-fixture-worker", daemon=False) thread.start() assert ready.wait(5) and servers and not errors sequence = 0 calls = []
def request(method, path, *, operation=None, args=None): nonlocal sequence headers = {"Authorization": "Bearer " + (config["read_token"] if method == "GET" else config["token"])} payload = None if method == "POST": payload = c.canonical(dict(version=c.VERSION, session=config["session"], sequence=sequence + 1, op=operation, args=args)) headers["Content-Type"] = "application/json" connection = http.client.HTTPConnection("127.0.0.1", servers[0].server_port, timeout=5) try: connection.request(method, path, body=payload, headers=headers) response = connection.getresponse() data = response.read() decoded = json.loads(data) if response.getheader("Content-Type") == "application/json" else None result = {"method": method, "path": path, "operation": operation, "credential_role": role + ("_read" if method == "GET" else "_rpc"), "session_matches_fixture": True, "next_sequence": sequence + 1 if payload else None, "http_status": response.status, "error": decoded.get("error") if isinstance(decoded, dict) else None, "response_bytes_sha256": _sha(data), "request_payload_sha256": None if payload is None else _sha(payload), "argument_keys": sorted(args) if isinstance(args, dict) else [], "requested_logical_asset": args.get("asset") if isinstance(args, dict) else None, "arguments_sha256": c.digest(args) if args is not None else None} calls.append(result) if method == "POST" and response.status == 200: sequence += 1 return result, decoded, data finally: connection.close()
state = {"source": source, "original_sha256": _sha(original), "counts": counts, "calls": calls, "births": births, "request": request, "role": role} try: yield state finally: if thread.is_alive(): reply, _, _ = request("POST", "/rpc", operation="close", args={}) assert reply["http_status"] == 200 thread.join(5) assert not thread.is_alive() and not errors owned_threads = [item for item in threading.enumerate() if item not in initial_threads] for item in owned_threads: item.join(2) assert not any(item.is_alive() for item in owned_threads) state["cleanup"] = {"worker_thread_joined": True, "server_closed": servers[0].fileno() == -1, "owned_subprocesses": 0, "all_created_threads_joined": True, "source_after_sha256": _sha(source.read_bytes()), "seconds": time.monotonic() - started}
def _probe_summary(state, valid, denied, before): after = dict(state["counts"]) return {"classification": "CURRENT_LOCAL_BOUNDARY_PROBE", "instrumentation_scope": "IN_PROCESS_PRODUCTION_HANDLER_THREADS", "fixture_scope": "OWNED_LOOPBACK_SERVICE_WITH_GENERATED_8X8_PNG_NO_WORKSPACE", "valid_counterpart": valid, "denied_requests": denied, "observed_sink_attempts": {k: after[k] - before[k] for k in before}, "canary_before_sha256": state["original_sha256"], "canary_after_sha256": _sha(state["source"].read_bytes()), "fixture_birth": state["births"], "fixture_loopback_requests": len(state["calls"])}
def test_A01_explicit_raw_read_is_denied_after_valid_derived_frame(tmp_path, monkeypatch, evidence): with _service("display", tmp_path, monkeypatch) as state: png = _image() put, _, _ = state["request"]("POST", "/rpc", operation="put", args={ "png": base64.b64encode(png).decode(), "sha256": _sha(png), "frame_ref": "ews:frame:fixture"}) valid, _, returned = state["request"]("GET", "/frame/ews:frame:fixture") assert put["http_status"] == valid["http_status"] == 200 and returned == png before = dict(state["counts"]) denied, _, _ = state["request"]("GET", "/sources/asset:1/raw") result = _probe_summary(state, valid, [denied], before) result["cleanup"] = state["cleanup"] result["fixture_loopback_requests"] = len(state["calls"]) result["all_request_records"] = state["calls"] evidence("EW-A01", result) assert denied["http_status"] == 403 and denied["error"] == "derived_frame_only" assert not any(result["observed_sink_attempts"].values()) assert result["canary_before_sha256"] == result["canary_after_sha256"] == result["cleanup"]["source_after_sha256"]
