def test_native_bsep_projection_binds_exact_dto_and_public_validator(real_package): document = _documents(real_package)["bsep_safe_projection_v01.json"] native = document["summary"]["native_bsep"] assert native["projection_kind"] == "NATIVE_DTO_SAFE_DERIVATIVE" assert native["canonical_native_dto_sha256"] == NATIVE_BSEP_SHA256 assert native["source_file"] == NATIVE_BSEP_SOURCE assert native["source_file_sha256"] == "67eff98a00873b68690ce691d9a7b5145bbf7f8802c82e2251b852b79e597d32" assert native["packet_pointer"] == "/source_context/g2c_source_context/bsep_packet" assert native["binding_pointer"] == "/source_context/router_input/bsep_binding" assert native["packet_type"] == "BoundedSemanticEvidencePacket" assert native["schema_version"] == "bounded_semantic_evidence_packet_v0.1" assert native["offline_validation"]["packet_accepted"] is True assert native["offline_validation"]["packet_reasons"] == [] assert native["authority_boundary_flags"]["authority_claimed"] is False assert native["authority_boundary_flags"]["action_permission_claimed"] is False assert "compiled_contract_summary" in document["summary"] with _runtime_guard("native_bsep_public_subset_validation", real_package["observations"]): real_package["adapter"]._validate_native_bsep_projection(native) real_package["observations"][-1].update(source_file=NATIVE_BSEP_SOURCE, canonical_native_dto_sha256=NATIVE_BSEP_SHA256, private_native_packet_published=False) real_package["observations"].flush()
@pytest.mark.parametrize("attack", ["missing_packet", "missing_binding", "packet_type", "schema", "source_role", "authority", "binding_digest", "binding_role"]) def test_native_bsep_source_and_binding_negatives(real_package, attack): # Private native input is read only; neither original nor altered DTO is emitted. data = (Path(os.environ["EWS4_INPUT_ROOT"]) / NATIVE_BSEP_SOURCE).read_bytes() assert _sha(data) == "67eff98a00873b68690ce691d9a7b5145bbf7f8802c82e2251b852b79e597d32" base = json.loads(data) context = base["source_context"] packet = context["g2c_source_context"]["bsep_packet"] binding = context["router_input"]["bsep_binding"] if attack == "missing_packet": del context["g2c_source_context"]["bsep_packet"] elif attack == "missing_binding": del context["router_input"]["bsep_binding"] elif attack == "packet_type": packet["packet_type"] = "UntrustedReplacementPacket" elif attack == "schema": packet["schema_version"] = "unsupported_test_schema" elif attack == "source_role": packet["source_role"] = "unexpected_role" elif attack == "authority": packet["authority_claimed"] = True elif attack == "binding_digest": binding["source_packet_sha256"] = "0" * 64 else: binding["target_role"] = "unexpected_role" with _runtime_guard("native_bsep_source_" + attack, real_package["observations"]): with pytest.raises(ValueError) as caught: real_package["adapter"]._native_bsep_projection(base) reason = str(caught.value) assert reason in {"native_bsep_missing_packet_or_binding", "native_bsep_dto_invalid", "native_bsep_binding_mismatch", "native_bsep_source_digest_mismatch"} real_package["observations"][-1].update(rejection_reason=reason, mutation={"kind": attack, "source_file": NATIVE_BSEP_SOURCE, "original_sha256": _sha(data), "private_dto_emitted": False}) real_package["observations"].flush()
@pytest.mark.parametrize("attack", ["role", "authority", "source_pointer", "source_digest"]) def test_native_bsep_public_claim_changes_cannot_reseal(real_package, tmp_path, attack): documents = _documents(real_package) native = documents["bsep_safe_projection_v01.json"]["summary"]["native_bsep"] if attack == "role": native["target_role"] = "unexpected_role" elif attack == "authority": native["authority_boundary_flags"]["authority_claimed"] = True elif attack == "source_pointer": native["packet_pointer"] = "/source_context/unrelated_packet" else: native["canonical_native_dto_sha256"] = "0" * 64 with _runtime_guard("native_bsep_projection_" + attack, real_package["observations"]): with pytest.raises(ValueError) as caught: real_package["adapter"]._write_package(documents, tmp_path / "altered_bsep") assert str(caught.value) == "native_bsep_projection_mismatch" assert not (tmp_path / "altered_bsep").exists() real_package["observations"][-1].update(rejection_reason=str(caught.value), mutation={"kind": attack, "scope": "valid_json_safe_bsep_projection"}) real_package["observations"].flush()
@pytest.mark.parametrize("attack,expected", [ ("missing_path", "candidate_source_ledger_scope_invalid"), ("unexpected_path", "candidate_source_ledger_scope_invalid"), ("changed_frozen_source", "frozen_predecessor_source_changed"), ]) def test_exact_27_path_ledger_rejects_scope_or_frozen_source_changes(real_package, tmp_path, attack, expected): original_path = Path(os.environ["EWS4_SOURCE_LEDGER"]) rows = json.loads(original_path.read_bytes()) assert len(rows) == 27 root = tmp_path / "altered_source_review" root.mkdir() for row in rows: target = root / row["source_object"] target.parent.mkdir(parents=True, exist_ok=True) target.write_bytes((original_path.parent / row["source_object"]).read_bytes()) if attack == "missing_path": rows.pop() elif attack == "unexpected_path": row = next(item for item in rows if item["path"] == "tests/test_ephemeral_workspace_adversarial_v01.py") row["path"] = "tests/unlisted_boundary_test.py" else: row = next(item for item in rows if item["path"] == "hedgehog/domains/ephemeral_workspace/semantic_roles_v01.py") body = (root / row["source_object"]).read_bytes() + b"\n# Controlled negative source mutation.\n" row.update(bytes=len(body), sha256=_sha(body), source_object="source_objects/" + _sha(body)) (root / row["source_object"]).write_bytes(body) path = root / "source_ledger.json" path.write_bytes(_json_bytes(rows)) with _runtime_guard("ledger_" + attack, real_package["observations"]): with pytest.raises(ValueError) as caught: real_package["adapter"]._source_ledger(path) assert str(caught.value) == expected real_package["observations"][-1].update(rejection_reason=str(caught.value), mutation={"kind": attack, "source_ledger_sha256": _sha(path.read_bytes()), "actual_candidate_changed": False, "row_count": len(rows)}) real_package["observations"].flush()
def _load_current_supplement(real_package, root, expected): documents = _documents(real_package) final = documents["final_safe_execution_report_v01.json"] return real_package["adapter"]._load_supplemental_proof(root, expected, source_ledger_rows=json.loads(Path(os.environ["EWS4_SOURCE_LEDGER"]).read_bytes()), principal_sources=real_package["report"]["source_records"], principal_facts=final["summary"]["facts"])
def test_supplemental_manifest_requires_explicit_matching_digest(real_package): with _runtime_guard("supplemental_wrong_caller_digest", real_package["observations"]): with pytest.raises(ValueError) as caught: _load_current_supplement(real_package, Path(os.environ["EWS4R_SUPPLEMENTAL_PROOF_ROOT"]), "0" * 64) assert str(caught.value) == "supplemental_manifest_mismatch" real_package["observations"][-1].update(rejection_reason=str(caught.value), expected_manifest="0" * 64, pin_scope="CONTROLLED_SUPPLEMENTAL_INPUT_NEGATIVE") real_package["observations"].flush()
@pytest.mark.parametrize("attack", ["bound_file_bytes", "coverage_classification", "recorded_observation"]) def test_supplemental_coverage_and_execution_bindings_reject_changes(real_package, tmp_path, attack): root = tmp_path / "supplemental_negative" shutil.copytree(Path(os.environ["EWS4R_SUPPLEMENTAL_PROOF_ROOT"]), root) manifest_path = root / "MANIFEST.json" original_manifest = manifest_path.read_bytes() manifest = json.loads(original_manifest) plan_path = root / "coverage_plan.json" plan = json.loads(plan_path.read_bytes()) row = next(item for item in plan["rows"] if item["requirement"] == "EW-A01") if attack == "bound_file_bytes": plan_path.write_bytes(plan_path.read_bytes() + b" ") expected = _sha(original_manifest) else: if attack == "coverage_classification": row["classification"] = "CARRIED_PRIOR_EVIDENCE" plan_path.write_bytes(_json_bytes(plan)) changed = "coverage_plan.json" else: changed = row["proof_refs"]["observation"] observation_path = root / changed observation = json.loads(observation_path.read_bytes()) observation["observed_sink_attempts"]["source_read_attempts"] = 1 observation_path.write_bytes(_json_bytes(observation)) entry = next(item for item in manifest if item["path"] == changed) data = (root / changed).read_bytes() entry.update(bytes=len(data), sha256=_sha(data)) manifest_path.write_bytes(_json_bytes(manifest)) expected = _sha(manifest_path.read_bytes()) with _runtime_guard("supplemental_" + attack, real_package["observations"]): with pytest.raises(ValueError) as caught: _load_current_supplement(real_package, root, expected) reason = str(caught.value) if attack == "bound_file_bytes": assert reason == "supplemental_file_digest_mismatch" elif attack == "coverage_classification": assert reason == "supplemental_coverage_scope_invalid" else: assert reason in {"supplemental_observation_mismatch", "supplemental_source_binding_mismatch", "supplemental_execution_record_binding_mismatch", "supplemental_receipt_binding_mismatch"} real_package["observations"][-1].update(rejection_reason=reason, mutation={"kind": attack, "expected_manifest_sha256": expected, "original_manifest_sha256": _sha(original_manifest), "principal_and_genuine_supplement_unchanged": True}) real_package["observations"].flush()
@pytest.mark.parametrize("attack", ["failed_call_phase", "nonzero_source_access"]) def test_public_coverage_claims_cannot_be_resealed_by_updating_summary_hash(real_package, tmp_path, attack): documents = _documents(real_package) coverage = documents["adversarial_matrix_v01.json"]["summary"] row = next(item for item in coverage["coverage"] if item["requirement"] == "EW-A01") if attack == "failed_call_phase": row["call_phase"]["outcome"] = "failed" else: row["observed_proof"]["observed_sink_attempts"]["source_read_attempts"] = 1 # Keep the summary digest coherent so this reaches the semantic proof guard. documents["final_safe_execution_report_v01.json"]["summary"]["supplemental_proof_binding"]["safe_coverage_sha256"] = real_package["adapter"]._digest(coverage) with _runtime_guard("public_coverage_" + attack, real_package["observations"]): with pytest.raises(ValueError) as caught: real_package["adapter"]._write_package(documents, tmp_path / "changed_coverage") assert str(caught.value) == "supplemental_projection_mismatch" assert not (tmp_path / "changed_coverage").exists() real_package["observations"][-1].update(rejection_reason=str(caught.value), mutation={"kind": attack, "requirement": "EW-A01", "summary_digest_recomputed": True, "source_evidence_unchanged": True}) real_package["observations"].flush()

"""Simulated-clock temporal boundaries with real public Root/Host builders.
These cheap tests stage read-side media fields and stop before common E. They never manufacture D/E returns or claim physical elapsed-time browser evidence. """ from copy import deepcopy from dataclasses import asdict import os from pathlib import Path from types import SimpleNamespace
import pytest
from demo.ephemeral_workspace_fixtures_v01 import generate from hedgehog import action_commit_packet_v02 as action from hedgehog import work_execution_host_v01 as hosts from hedgehog.domains.ephemeral_workspace import contracts_v01 as c from hedgehog.domains.ephemeral_workspace import kernel_adapter_v01 as kernel from hedgehog.domains.ephemeral_workspace import media_continuation_v01 as continuation from hedgehog.domains.ephemeral_workspace import session_runtime_v01 as runtime from hedgehog.domains.ephemeral_workspace.local_services_v01 import Service from hedgehog.domains.ephemeral_workspace.evidence_v01 import media_value
class StopBeforeE(ValueError): """Test-only boundary; not a recomputation result."""
def record(name, value): directory = os.environ.get('EWS_TEMPORAL_EVIDENCE') if directory: path = Path(directory) / (name + '.json') path.parent.mkdir(parents=True, exist_ok=True) path.write_bytes(c.canonical(dict( scope='SIMULATED_CLOCK_STAGED_MEDIA_FIELDS_REAL_ROOT_HOST_NO_D_OR_E', **value)) + b'\n')
@pytest.fixture def pending_workspace(tmp_path): expected = os.environ.get('EWS_EXPECTED_CANDIDATE') if expected: assert Path(runtime.__file__).resolve().is_relative_to(Path(expected)) session = runtime.Workspace(tmp_path / 'workspace', generate(tmp_path / 'photos', 1)) try: session.command('OPEN') # Staged read-side fixture only. The photo Work and Root/Host are real; # no media D or E result is constructed or substituted by this fixture. session.contract = dict(session.contract, media=dict(audio=True)) session.allowed += ('PLAY', 'PAUSE', 'SEEK', 'REVIEW_MEDIA') audio = Service('audio', session.id, session.deadline, session.directory / 'logs') session.services.append(audio) session.resource_plan['audio'] = audio.nonce session.media_review = dict( output=dict(audio=True, audio_policy='SILENT_CONTINUE'), results=(SimpleNamespace(result=SimpleNamespace(result_id='ews:test:staged_read_side_media')),)) session.media_state.update(audio='AVAILABLE', status='READY') authorization, inputs, observation, review = kernel.prepare_command( session, dict(op='SEEK', value=7), dict(test_scoped_pending=True)) clock = session.source.sample(observation) packet, _ = hosts.install_current_action_v01( session.host, **authorization, inputs=inputs, admission_id=session.catalogue[2].admission_id, expected_revision=session.host.revision, evaluation_time=clock.evaluation_time, evaluation_time_source=clock.evaluation_time_source, evaluation_context_id=clock.evaluation_context_id) session.media_pending = dict(authorization=authorization, inputs=inputs, observation=observation, review=review, packet_id=packet, fact=session.last_prepared_fact, registry=session.host.registry) session.media_baseline = dict(scope='STAGED_NOT_A_D_BASELINE', photo_work=session.photo_work()) yield session finally: cleanup = session.close('TEMPORAL_TEST_RESOURCE_FINALIZER') assert cleanup['status'] == 'CLOSED_SUCCESS' assert all(service.process.poll() is not None for service in session.services)
def simulated_clock(monkeypatch, session, timestamp): # Replace only each domain module's clock reference. Service/process clocks # keep real time; no clock replacement escapes this deterministic test. clock = {'utc': timestamp} local = SimpleNamespace(monotonic=lambda: session.source.started + clock['utc'] - session.source.epoch + 0.25) monkeypatch.setattr(runtime, 'time', local) monkeypatch.setattr(kernel, 'time', local) return clock
def stop_before_native_e(monkeypatch, calls): def stop(session, capture, invalidation, observed_time): calls.append((capture, invalidation, observed_time)) raise StopBeforeE('test_stopped_during_pre_E_preparation') # Exercise the actual recompute entry's preparation/error boundary while # avoiding its expensive native E invocation and any synthetic E success. monkeypatch.setattr(continuation, 'delta_arguments', stop)
@pytest.mark.parametrize('relative_to_expiry', [-1, 0, 1]) def test_actual_loss_observation_has_new_interval_and_immutable_old_authority( pending_workspace, monkeypatch, relative_to_expiry): session = pending_workspace pending = session.media_pending original = c.canonical(media_value(pending)) baseline = deepcopy(session.media_baseline) photo = session.photo_work() pixels = session.photo_frame(session.preview['frame_ref']) prior = pending['observation'] old_bound = pending['authorization']['root_bound'] now = prior.valid_to_utc + relative_to_expiry simulated_clock(monkeypatch, session, now) calls = [] stop_before_native_e(monkeypatch, calls) effects = deepcopy(session.executed) history = deepcopy(session.history) with pytest.raises(StopBeforeE, match='test_stopped_during_pre_E_preparation'): session.withdraw_audio() assert len(calls) == 1 capture, invalidation, observed_time = calls[0] observation, = capture.observations assert observed_time == now == observation.observed_at_utc == observation.valid_from_utc assert observation.valid_to_utc == min(now + 120, session.expires) assert observation.valid_from_utc <= capture.evaluation_time < observation.valid_to_utc assert observation.dependency_id == prior.dependency_id assert observation.evidence_ref == prior.evidence_ref assert observation.freshness_policy_id == prior.freshness_policy_id assert observation.source_provenance_refs == prior.source_provenance_refs assert observation.time_envelope_id != prior.time_envelope_id assert observation.observed_content_sha256 == c.digest(dict(pending['fact'], media=session.loss_dependency)) assert observation.observed_content_sha256 != prior.observed_content_sha256 assert action.validate_action_dependency_time_envelope_binding_v01( observation.time_envelope_id, dependency_id=observation.dependency_id, evidence_ref=observation.evidence_ref, content_sha256=observation.observed_content_sha256, freshness_policy_id=observation.freshness_policy_id, source_provenance_refs=observation.source_provenance_refs, valid_from_utc=observation.valid_from_utc, valid_to_utc=observation.valid_to_utc) == (True, ()) assert capture.root_bound_packet == old_bound assert capture.root_bound_packet.canonical_projection.temporal_authority == old_bound.canonical_projection.temporal_authority assert hosts.validate_retained_action_source_capture_v01(session.host, capture, require_current=True) assert invalidation.packet_id == pending['packet_id'] assert invalidation.dependency_id == prior.dependency_id assert invalidation.time_envelope_id == prior.time_envelope_id assert invalidation.evidence_sha256 == observation.observed_content_sha256 assert c.canonical(media_value(session.media_pending)) == original assert session.media_baseline == baseline assert session.photo_work() == photo assert session.photo_frame(session.preview['frame_ref']) == pixels assert session.executed == effects and session.history == history assert session.audio_loss['stale_packet_refusal'] == 'host_current_action_not_executable' assert session.media_delta is None and session.producer_counts['delta'] == 0 assert session.media_state['status'] == 'AUDIO_UNAVAILABLE_PAUSED' assert session.media_state['reason'] == 'StopBeforeE:test_stopped_during_pre_E_preparation' assert session.state()['owner_cleanup_available'] record('boundary_' + str(relative_to_expiry).replace('-', 'minus'), dict( original_observation=asdict(prior), changed_observation=asdict(observation), temporal_authority=asdict(old_bound.canonical_projection.temporal_authority), actual_test_error=session.audio_loss['continuation_error'], invalidation=asdict(invalidation), capture=dict(source_revision=capture.source_revision, host_revision=capture.host_revision, ordinal=capture.capture_ordinal, evaluation_time=capture.evaluation_time), relative_to_original_expiry=relative_to_expiry, effect_count_before=len(effects), effect_count_after=len(session.executed), source_offset=session.source.offset, photo_sha256=c.digest(pixels)))
@pytest.mark.parametrize('relative_to_expiry', [0, 1]) def test_original_expired_packet_refusal_does_not_depend_on_new_observation( pending_workspace, monkeypatch, relative_to_expiry): session = pending_workspace pending = session.media_pending original = c.canonical(media_value(pending)) prior = pending['observation'] simulated_clock(monkeypatch, session, prior.valid_to_utc + relative_to_expiry) before = deepcopy(session.executed) clock = session.source.sample() # No loss and no changed observation. assert prior in clock.observations with pytest.raises(ValueError, match='^host_current_action_not_executable$'): hosts.dispatch_current_action_v01(session.host, packet_id=pending['packet_id'], task_id=session.id, expected_revision=session.host.revision, evaluation_time=clock.evaluation_time, evaluation_time_source=clock.evaluation_time_source, evaluation_context_id=clock.evaluation_context_id) assert session.executed == before assert c.canonical(media_value(session.media_pending)) == original assert session.audio_loss is None and session.media_delta is None assert not hasattr(session, 'audio_capture') record('independent_refusal_' + str(relative_to_expiry), dict( observation=asdict(prior), packet_id=pending['packet_id'], evaluation_time=clock.evaluation_time, effect_count_before=len(before), effect_count_after=len(session.executed), no_changed_observation=True))
def test_new_observation_interval_is_capped_by_workspace_expiry(pending_workspace, monkeypatch): session = pending_workspace now = session.media_pending['observation'].valid_to_utc + 1 session.expires = now + 30 # Test-only narrowing; old packet remains unchanged. simulated_clock(monkeypatch, session, now) calls = [] stop_before_native_e(monkeypatch, calls) with pytest.raises(StopBeforeE): session.withdraw_audio() observation, = session.audio_capture.observations assert observation.valid_from_utc == now assert observation.valid_to_utc == session.expires == now + 30 record('session_cap', dict(observation=asdict(observation), workspace_expires=session.expires))
def test_expiry_at_acquisition_is_truthful_pre_e_failure(pending_workspace, monkeypatch): session = pending_workspace clock = simulated_clock(monkeypatch, session, session.expires - 1) # Keep this probe about the whole session boundary rather than its idle rule. session.last_activity = runtime.time.monotonic() audio = next(service for service in session.services if service.role == 'audio') close = audio.close def close_at_expiry(): receipt = close() clock['utc'] = session.expires return receipt monkeypatch.setattr(audio, 'close', close_at_expiry) calls = [] stop_before_native_e(monkeypatch, calls) before = deepcopy(session.executed) photo = session.photo_work() with pytest.raises(ValueError, match='^workspace_expired$'): session.withdraw_audio() assert calls == [] and not hasattr(session, 'audio_capture') assert session.audio_loss['continuation_error'] == dict(type='ValueError', reason='workspace_expired') assert session.media_state['status'] == 'AUDIO_UNAVAILABLE_PAUSED' assert session.media_state['audio'] == 'UNAVAILABLE' assert session.media_state['reason'] == 'ValueError:workspace_expired' assert session.media_delta is None and session.producer_counts['delta'] == 0 assert session.executed == before and session.photo_work() == photo state = session.state() assert state['status'] == 'EXPIRED' and state['allowed'] == [] assert state['owner_cleanup_available'] and not state['owner_approval_available'] record('acquisition_expired', dict(error=session.audio_loss['continuation_error'], state=state))
@pytest.mark.parametrize('closed_by', ['expiry', 'revocation']) def test_no_continuation_action_or_save_authority_when_workspace_not_current( pending_workspace, monkeypatch, closed_by): session = pending_workspace session.edits['asset:1']['selected'] = True candidate = session.save_candidate() session.pending = candidate if closed_by == 'expiry': simulated_clock(monkeypatch, session, session.expires) else: session.revoke() # Real current local Root withdrawal and owned cleanup. assert session.withdrawal['decision'] == 'ACCEPT' source_before = session.source.snapshot effects_before = deepcopy(session.executed) calls = [] stop_before_native_e(monkeypatch, calls) for operation in (session.withdraw_audio, lambda: session.command('PLAY'), lambda: session.command('REQUEST_SAVE'), lambda: session.approve(candidate)): with pytest.raises(ValueError, match='workspace_(expired|not_current)'): operation() assert session.source.snapshot == source_before assert session.executed == effects_before and session.approvals == {} assert session.saved is None and session.write_outcome == 'NOT_STARTED' assert calls == [] and session.audio_loss is None and session.media_delta is None state = session.state() assert not state['current'] and not state['owner_approval_available'] if closed_by == 'expiry': assert state['owner_cleanup_available'] cleanup = session.close('TEMPORAL_BOUNDARY_OWNER_CLEANUP') assert cleanup['status'] == 'CLOSED_SUCCESS' assert cleanup['authority'] == 'INITIAL_RESOURCE_OWNER_CLEANUP_OBLIGATION' assert all(service.process.poll() is not None for service in session.services) assert not list((session.directory / 'output').iterdir()) record('denied_' + closed_by, dict(state=state, cleanup=cleanup, effects_before=len(effects_before), effects_after=len(session.executed), sidecar_files=[]))

