def private_image(path, kind='PNG'):
    image=Image.new('RGB',(80,40),(93,120,47))
    exif=Image.Exif()
    exif[274]=6
    exif[315]='PRIVATE_ARTIST_CREDENTIAL'
    exif[34853]={1:'N',2:(12,34,56),3:'E',4:(65,43,21)}
    options=dict(exif=exif)
    if kind=='PNG':
        info=PngImagePlugin.PngInfo()
        info.add_text('source_path','/private/PRIVATE_SOURCE_PATH.png')
        info.add_itxt('credentials','PRIVATE_CREDENTIAL_TOKEN')
        options['pnginfo']=info
    image.save(path,format=kind,**options)
    return path.read_bytes()


@pytest.mark.parametrize('kind',('PNG','JPEG'))
def test_render_unconditionally_strips_exif_gps_and_png_metadata(tmp_path,kind):
    source=tmp_path/('private.'+kind.lower())
    original=private_image(source,kind)
    with Image.open(BytesIO(original)) as image:
        assert image.getexif()[315]=='PRIVATE_ARTIST_CREDENTIAL'
        assert image.getexif().get_ifd(34853)[1]=='N'
    png=render(original,0,'ORIGINAL')
    assert preview_dimensions(png)==(40,80)
    with Image.open(BytesIO(png)) as image:
        assert image.info=={} and not image.getexif()
    assert b'PRIVATE_' not in png and source.read_bytes()==original


@pytest.mark.parametrize('minimize',('preview_only','preview_without_metadata'))
def test_real_privacy_services_enforce_projection_metadata_and_refusal_recovery(tmp_path,minimize):
    source=tmp_path/'private.png'
    original=private_image(source)
    logs=tmp_path/'logs';logs.mkdir()
    media=Service('media','ews:privacy',time.monotonic()+60,logs,
        {'asset:1':[str(source),c.digest(original)]},minimize=minimize)
    display=None
    try:
        display=Service('display','ews:privacy',time.monotonic()+60,logs,minimize=minimize)
        response=media.rpc('render',dict(asset='asset:1',exposure=0,crop='ORIGINAL',preview='fit'))
        png=validate_transfer(response,minimize,('png','sha256','asset','session'))
        transfer=dict(png=response['png'],sha256=response['sha256'],frame_ref='ews:frame:privacy')
        if minimize=='preview_only':
            assert response['derived']==dict(width=40,height=80,exposure=0,crop='ORIGINAL',preview='fit')
            transfer['derived']=response['derived']
        else:
            assert set(response)=={'png','sha256','asset','session'}
        for secret in (str(source),'PRIVATE_',media.token,media.read_token,display.token,display.read_token):
            assert secret not in c.canonical(response).decode()
        assert preview_dimensions(png)==(40,80)
        receipt=display.rpc('put',transfer)
        assert receipt['minimize']==minimize and receipt['transfer_fields']==sorted(transfer)
        assert receipt['transfer_sha256']==c.digest(transfer)
        attacks=[]
        for field in ('source_path','exif','gps','credentials'):
            attack=deepcopy(transfer);attack[field]='forbidden';attacks.append(attack)
        attack=deepcopy(transfer)
        if minimize=='preview_only':
            attack.pop('derived')
        else:
            attack['derived']=dict(width=40,height=80,exposure=0,crop='ORIGINAL',preview='fit')
        attacks.append(attack)
        if minimize=='preview_only':
            for key,value in [('width',True),('height',79),('exposure',True),('crop','/private/source'),('preview','contain'),('credentials','forbidden')]:
                attack=deepcopy(transfer);attack['derived'][key]=value;attacks.append(attack)
        dirty=deepcopy(transfer)
        dirty.update(png=base64.b64encode(original).decode(),sha256=c.digest(original))
        attacks.append(dirty)
        for attack in attacks:
            with pytest.raises(urllib.error.HTTPError) as error:
                display.rpc('put',attack)
            assert error.value.code==403
            with request(display.url+'/frame/ews:frame:privacy',display.read_token) as frame:
                assert frame.read()==png
            assert display.rpc('put',deepcopy(transfer))==receipt
        with pytest.raises(urllib.error.HTTPError):
            media.rpc('render',dict(asset='asset:1',exposure=0,crop='ORIGINAL',preview='contain'))
        assert media.rpc('render',dict(asset='asset:1',exposure=0,crop='ORIGINAL',preview='fit'))==response
        source.rename(tmp_path/'preserved-source.png')
        with pytest.raises(urllib.error.HTTPError) as error:
            media.rpc('render',dict(asset='asset:1',exposure=0,crop='ORIGINAL',preview='fit'))
        assert json.load(error.value)==dict(error='service_io_unavailable')
        (tmp_path/'preserved-source.png').rename(source)
        assert source.read_bytes()==original
    finally:
        if display:assert display.close()['reaped']
        assert media.close()['reaped']


class PrivacyVariant(roles.ControlledProvider):
    def __init__(self,minimize,block=False):
        self.minimize,self.block=minimize,block

    def respond(self,role,context):
        value=super().respond(role,context)
        if role==roles.ROLES[2]:
            value.update(minimize=self.minimize)
            if self.block:value.update(decision='block',conflicts=['Unapproved display requested.'])
        return value


def test_compiled_privacy_policy_consumed_by_actual_session_after_refusal(tmp_path):
    source=tmp_path/'private.png'
    original=private_image(source)
    with pytest.raises(ValueError,match='privacy_refusal'):
        Workspace(tmp_path/'blocked',(source,),provider=PrivacyVariant('preview_only',block=True))
    assert not (tmp_path/'blocked'/'logs').exists()
    observations=[]
    for minimize in ('preview_only','preview_without_metadata'):
        session=Workspace(tmp_path/minimize,(source,),provider=PrivacyVariant(minimize))
        try:
            assert session.contract==roles.compile_contract([capture['output'] for capture in session.captures])
            assert session.work_results[1].consumed_fields[0].disposition=='USED'
            session.command('OPEN')
            session.command('EXPOSURE',3)
            report=session.report()
            consumption=report['privacy_consumption']
            assert consumption['minimize']==minimize and len(consumption['transfers'])==2
            for service in session.services:
                assert service.config['minimize']==session.contract['minimize']
                assert service.config['preview']==session.contract['preview']
            for i,transfer in enumerate(consumption['transfers']):
                assert transfer['minimize']==minimize and transfer['contract_sha256']==c.digest(session.contract)
                assert transfer['png_metadata']=='ABSENT_VERIFIED'
                assert transfer['media_sha256']==session.services[0].events[i]['response_sha256']
                assert transfer['display_receipt_sha256']==session.services[1].events[i]['response_sha256']
                assert set(transfer['media_fields'])=={'png','sha256','asset','session'}|({'derived'} if minimize=='preview_only' else set())
                assert set(transfer['display_fields'])=={'png','sha256','frame_ref'}|({'derived'} if minimize=='preview_only' else set())
                assert transfer['derived_fields']==(sorted(('width','height','exposure','crop','preview')) if minimize=='preview_only' else [])
            assert consumption['transfers'][0]['png_sha256']!=consumption['transfers'][1]['png_sha256']
            observations.append(consumption['transfers'])
            assert report['source_preserved'] and source.read_bytes()==original
            assert len(session.history)==2
        finally:
            assert session.close()['status']=='CLOSED_SUCCESS'
    assert [t['png_sha256'] for t in observations[0]]==[t['png_sha256'] for t in observations[1]]


@pytest.mark.parametrize('minimize',('preview_only','preview_without_metadata'))
def test_session_refuses_invalid_media_projection_before_display(tmp_path,monkeypatch,minimize):
    assets=generate(tmp_path/'sources',1)
    session=Workspace(tmp_path/'workspace',assets,provider=PrivacyVariant(minimize))
    try:
        session.command('OPEN')
        original=session.services[0].rpc
        calls=len(session.services[1].events)
        def tampered(op,args):
            response=original(op,args)
            if op=='render':
                if minimize=='preview_only':response['derived']['exposure']=19
                else:response['derived']=dict(width=1,height=1,exposure=0,crop='ORIGINAL',preview='fit')
            return response
        monkeypatch.setattr(session.services[0],'rpc',tampered)
        with pytest.raises(ValueError):
            session.command('EXPOSURE',2)
        assert len(session.services[1].events)==calls
        assert len(session.privacy_transfers)==1
        state=session.state()
        assert state['status']=='PREVIEW_UNAVAILABLE' and not state['current'] and state['allowed']==[] and state['preview'] is None
        with pytest.raises(ValueError,match='workspace_not_current'):
            session.command('NEXT')
    finally:
        session.close()


@pytest.mark.parametrize('foreign',('none','replacement','directory','dangling_symlink'))
def test_http_control_save_owner_approval_and_truthful_close(tmp_path,foreign):
    assets=generate(tmp_path/'sources',1)
    source_hashes=[c.digest(p.read_bytes()) for p in assets]
    session=Workspace(tmp_path/'workspace',assets)
    viewer=None
    try:
        session.command('OPEN')
        viewer=Viewer(session)
        for sequence,op,value in [(1,'SELECT',True),(2,'REQUEST_SAVE',None)]:
            body=dict(version=1,session=session.id,sequence=sequence,command=dict(op=op,value=value))
            with request(viewer.control_url+'/command',viewer.control_token,body) as response:
                state=json.load(response)
        pending=state['pending']
        assert state['owner_approval_available'] and pending
        with pytest.raises(urllib.error.HTTPError):
            request(viewer.owner_url+'/approve',viewer.control_token,dict(candidate=pending))
        with pytest.raises(urllib.error.HTTPError):
            request(viewer.owner_url+'/approve',viewer.owner_token,dict(candidate=pending),origin=viewer.control_url)
        with request(viewer.owner_url+'/approve',viewer.owner_token,dict(candidate=pending),origin=viewer.owner_url) as response:
            saved=json.load(response)['saved']
        output=session.directory/'output'/'selection.json'
        assert output.read_bytes()==c.canonical(pending['content'])+b'\n'
        assert c.digest(output.read_bytes())==saved['sha256'] and session.write_outcome=='WRITTEN_ONCE'
        assert len(session.history)==4 and all(record['packet_id'] for record in session.history)
        with pytest.raises(urllib.error.HTTPError):
            request(viewer.owner_url+'/approve',viewer.owner_token,dict(candidate=pending))
        path=next(iter(session.owned))
        if foreign!='none':
            path.unlink()
            if foreign=='replacement':path.write_bytes(b'foreign replacement')
            elif foreign=='directory':path.mkdir()
            else:path.symlink_to(tmp_path/'missing-target')
        ref=session.preview['frame_ref']
        with request(viewer.owner_url+'/end',viewer.owner_token,{}) as response:
            cleanup=json.load(response)
        expected='CLOSED_SUCCESS' if foreign=='none' else 'CLEANUP_INCOMPLETE'
        assert cleanup['status']==expected and cleanup['reason']=='OWNER_END'
        assert cleanup['authority']=='INITIAL_RESOURCE_OWNER_CLEANUP_OBLIGATION'
        assert len(session.history)==4
        assert cleanup['foreign_preserved']==([] if foreign=='none' else [path.name])
        if foreign!='none':
            assert path.name not in cleanup['removed'] and 'NOT_REMOVED' in cleanup['retained_reason']
            assert path.is_symlink() if foreign=='dangling_symlink' else path.exists()
        if foreign=='replacement':assert path.read_bytes()==b'foreign replacement'
        with request(viewer.owner_url+'/end',viewer.owner_token,{}) as response:
            assert json.load(response)==cleanup
        with request(viewer.control_url+'/state',viewer.control_token) as response:
            state=json.load(response)
        assert state['status']==expected and state['cleanup']==cleanup
        assert not state['current'] and not state['owner_approval_available'] and not state['owner_cleanup_available']
        assert state['allowed']==[] and state['preview'] is None and state['pending'] is None
        with pytest.raises(urllib.error.HTTPError):
            request(viewer.control_url+'/frame/'+ref,viewer.control_token)
        body=dict(version=1,session=session.id,sequence=3,command=dict(op='NEXT',value=None))
        with pytest.raises(urllib.error.HTTPError):
            request(viewer.control_url+'/command',viewer.control_token,body)
        assert all(service.process.poll() is not None for service in session.services)
        assert [c.digest(p.read_bytes()) for p in assets]==source_hashes
    finally:
        if viewer:viewer.close()
        session.close()


@pytest.mark.parametrize('stale',('expiry','idle','revoke'))
def test_http_state_currentness_without_effects_or_source_reads(tmp_path,monkeypatch,stale):
    assets=generate(tmp_path/'sources',1)
    class IdleVariant(roles.ControlledProvider):
        def respond(self,role,context):
            value=super().respond(role,context)
            if role==roles.ROLES[1] and stale=='idle':value['cleanup']='on_end_and_idle'
            return value
    session=Workspace(tmp_path/'workspace',assets,c.REQUEST_B,provider=IdleVariant())
    viewer=None
    try:
        session.command('OPEN')
        viewer=Viewer(session)
        ref=session.preview['frame_ref']
        if stale=='expiry':session.source.offset=1201
        elif stale=='idle':
            session.last_activity=time.monotonic()-301
        else:session.revoke()
        before=(session.host.revision,len(session.history),len(session.executed),session.status,session.cleanup_report,session.last_activity)
        read_bytes=Path.read_bytes
        def no_source_reads(path):
            assert path not in session.assets.values(),'state must not read sources'
            return read_bytes(path)
        with monkeypatch.context() as patch:
            patch.setattr(Path,'read_bytes',no_source_reads)
            for url,token in ((viewer.owner_url,viewer.owner_token),(viewer.control_url,viewer.control_token)):
                with request(url+'/state',token) as response:state=json.load(response)
                assert not state['current'] and state['allowed']==[] and state['preview'] is None and state['pending'] is None
                assert not state['owner_approval_available']
                assert state['status']==('CLOSED_SUCCESS' if stale=='revoke' else 'EXPIRED')
        assert before==(session.host.revision,len(session.history),len(session.executed),session.status,session.cleanup_report,session.last_activity)
        with pytest.raises(urllib.error.HTTPError):request(viewer.control_url+'/frame/'+ref,viewer.control_token)
        body=dict(version=1,session=session.id,sequence=1,command=dict(op='NEXT',value=None))
        with pytest.raises(urllib.error.HTTPError):request(viewer.control_url+'/command',viewer.control_token,body)
        assert len(session.history)==1
    finally:
        if viewer:viewer.close()
        session.close()

"""Focused EWS-1 contracts and actual common Root/Host consumption.""" from copy import deepcopy import json from pathlib import Path import pytest from demo.ephemeral_workspace_fixtures_v01 import generate from hedgehog.domains.ephemeral_workspace import contracts_v01 as c from hedgehog.domains.ephemeral_workspace import semantic_roles_v01 as roles, semantic_adapter_v01 as semantics from hedgehog.domains.ephemeral_workspace.session_runtime_v01 import Workspace from hedgehog.domains.ephemeral_workspace.media_v01 import render from hedgehog import work_execution_host_v01 as hosts
@pytest.fixture(scope='module') def assets(tmp_path_factory): return generate(tmp_path_factory.mktemp('ews_media')/'sources',6)
def test_role_causality_and_missing_fields_source_only(tmp_path,assets): class Variant(roles.ControlledProvider): def __init__(self,index,mutate): self.index,self.mutate=index,mutate def respond(self,role,context): value=super().respond(role,context) if role==roles.ROLES[self.index]: self.mutate(value) return value base=Workspace(tmp_path/'base',assets) variants=[Variant(0,lambda v:v['needs'].remove('crop')),Variant(1,lambda v:v.update(preview='contain'))] for i,provider in enumerate(variants): session=Workspace(tmp_path/str(i),assets,provider=provider) assert not session.services assert session.contract!=base.contract if i==0: with pytest.raises(ValueError,match='operation_not_allowed'): session.command('CROP','SQUARE') else: data=assets[0].read_bytes() assert render(data,0,'ORIGINAL',session.contract['preview'])!=render(data,0,'ORIGINAL',base.contract['preview']) session.close() with pytest.raises(ValueError,match='privacy_refusal'): Workspace(tmp_path/'block',assets,provider=Variant(2,lambda v:v.update(decision='block',conflicts=['Unapproved display requested.']))) for index,key in [(0,'needs'),(1,'phases'),(2,'decision')]: with pytest.raises(ValueError,match='semantic_closed_shape'): Workspace(tmp_path/f'absent{index}',assets,provider=Variant(index,lambda v,k=key:v.pop(k))) base.close()
def _write_capture_package(root, material): """Synthetic semantic evidence only; no Workspace, media fixture or provider call.""" root.mkdir(parents=True,exist_ok=True) manifest=[] for name,value in sorted(material.items()): data=c.canonical(value) path=root/name path.parent.mkdir(parents=True,exist_ok=True) path.write_bytes(data) manifest.append(dict(path=name,bytes=len(data),sha256=c.digest(data))) data=c.canonical(manifest) (root/'MANIFEST.json').write_bytes(data) return c.digest(data)
def _capture_package(tmp_path, *, live=False, asset_binding=True): base=dict(version=c.VERSION,request=c.REQUEST_A,capability_classes=list(c.CLASSES)) if asset_binding: base['asset_inventory']=[dict(asset='asset:1',sha256='a'*64)] records=[] for index,role in enumerate(roles.ROLES): context=deepcopy(base) if index: context.update(bsep=dict(needs=records[0]['output']['needs'],source_write=False,publication=False,separate_save=True), route_acceptance=dict(decision='ACCEPT',scope=records[0]['output']['needs'])) if index==2: context['obligations']=records[1]['output'] output=roles.ControlledProvider().respond(role,context) records.append(semantics.envelope(role,context,output,mode='LIVE' if live else 'CONTROLLED_DETERMINISTIC', model='gemini-2.5-flash' if live else roles.ControlledProvider.model, attempt=index+2 if live else 0,raw=c.canonical(output).decode())) material={'private/semantic_captures.json':records} attempts=[] if live: for number,record in enumerate([records[0]]+records,1): failed=number==1 attempt=dict(attempt=number,role=record['role'],model=record['model'],projection_ref=record['projection_ref'], status='FAILED' if failed else 'RETURNED',elapsed_seconds=0.25,response_model=record['model'], usage=dict(prompt_token_count=11,candidates_token_count=3,total_token_count=14)) raw=c.canonical(dict(output_contract=record['output'])).decode() if failed else record['raw'] if failed: attempt['error_type']='ValueError' else: attempt.update(response_ref=record['response_ref'],raw_sha256=c.digest(raw.encode())) attempts.append(attempt) material['private/budget/transport_%02d.json'%number]=dict(role=record['role'],context=record['context'], model=record['model'],attempt=number,raw=raw) material['private/budget/request_%02d.json'%number]=dict(role=record['role'],model=record['model'], contents=c.canonical(dict(role=record['role'],task=record['context'],required_top_level_fields=roles.SCHEMAS[record['order']])).decode(), system_instruction='Synthetic closed semantic object.',max_output_tokens=2048,automatic_retries=False, projection_ref=record['projection_ref']) material['private/budget/attempts.json']=attempts for index,record in enumerate(records,1): material['private/budget/capture_%02d.json'%index]=record root=tmp_path/'package' pin=_write_capture_package(root,material) config=dict(original_return_root=root,manifest_sha256=pin,expected_mode='LIVE' if live else 'CONTROLLED_DETERMINISTIC', records_path='private/semantic_captures.json',attempts_path='private/budget/attempts.json' if live else None) return config,material
def _reidentify_capture(record): record['raw']=c.canonical(record['output']).decode() record['request_ref']=c.identity('semantic_request',record['context']) record['projection_ref']=c.identity('semantic_projection',dict(role=record['role'],input=record['context'])) record['response_ref']=c.identity('semantic_response',{k:v for k,v in record.items() if k!='response_ref'})
def test_full_capture_binding_and_equivalent_copy_source_only(tmp_path,assets): original=Workspace(tmp_path/'original',assets) records=deepcopy(original.captures) package=tmp_path/'capture_origin' records_path='private/semantic_captures.json' pin=_write_capture_package(package,{records_path:deepcopy(original.captures)}) origin=semantics.load_capture_origin(package,manifest_sha256=pin,expected_mode='CONTROLLED_DETERMINISTIC', records_path=records_path) provider=semantics.CapturedProvider(records,[],origin=origin) fresh=Workspace(tmp_path/'fresh',assets,provider=provider) assert fresh.contract==original.contract and fresh.host is not original.host and fresh.id!=original.id for index in range(3): record=records[index] assert semantics.validate_capture(deepcopy(record),record['role'],record['context'])==record['output'] for key,value in [('response_ref','ews:wrong'),('request_ref','ews:wrong'),('order',True),('version','wrong'), ('model','forged'),('provider','other'),('raw','{}')]: changed=deepcopy(record);changed[key]=value with pytest.raises(ValueError): semantics.validate_capture(changed,record['role'],record['context']) changed=deepcopy(record);changed['output']['unexpected']=True with pytest.raises(ValueError): semantics.validate_capture(changed,record['role'],record['context']) assert provider.index==3 changed_context=deepcopy(records[0]['context']) changed_context['asset_inventory'][0]['sha256']='0'*64 with pytest.raises(ValueError,match='capture_input_binding'): semantics.validate_capture(records[0],records[0]['role'],changed_context) original.close();fresh.close()
@pytest.mark.parametrize('live',[False,True]) def test_capture_binding_and_equivalent_copy_without_workspace(tmp_path,live): config,_=_capture_package(tmp_path,live=live) origin=semantics.load_capture_origin(**config) records=semantics.parse(origin.records_bytes) attempts=semantics.parse(origin.attempts_bytes) provider=semantics.CapturedProvider(deepcopy(records),deepcopy(attempts),origin=origin) outputs=[] for index in range(3): record=records[index] outputs.append(provider.respond(record['role'],deepcopy(record['context']))) assert semantics.validate_capture(deepcopy(record),record['role'],record['context'])==record['output'] for key,value in [('response_ref','ews:wrong'),('request_ref','ews:wrong'),('order',True),('version','wrong'), ('model','forged'),('provider','other'),('raw','{}')]: changed=deepcopy(record);changed[key]=value with pytest.raises(ValueError): semantics.validate_capture(changed,record['role'],record['context']) changed=deepcopy(record);changed['output']['unexpected']=True with pytest.raises(ValueError): semantics.validate_capture(changed,record['role'],record['context']) assert provider.index==3 assert roles.compile_contract(outputs)==roles.compile_contract([r['output'] for r in records]) changed_context=deepcopy(records[0]['context']) changed_context['asset_inventory'][0]['sha256']='0'*64 with pytest.raises(ValueError,match='capture_input_binding'): semantics.validate_capture(records[0],records[0]['role'],changed_context) with pytest.raises(ValueError,match='capture_role_order'): provider.respond(records[0]['role'],records[0]['context'])
@pytest.mark.parametrize('attack',['downgrade','mixed','coherent_output','missing','extra','reordered','last_invalid','nested_type']) def test_capture_origin_rejects_reconstruction_before_consumption(tmp_path,attack): config,_=_capture_package(tmp_path,live=True) origin=semantics.load_capture_origin(**config) records=semantics.parse(origin.records_bytes) attempts=semantics.parse(origin.attempts_bytes) if attack in ('downgrade','mixed'): for record in records if attack=='downgrade' else records[1:2]: record.update(mode='CONTROLLED_DETERMINISTIC',provider='local',attempt=0) _reidentify_capture(record) if attack in ('downgrade','coherent_output'): records[1]['output']['preview']='contain' records[2]['context']['obligations']=deepcopy(records[1]['output']) for record in records: _reidentify_capture(record) elif attack=='missing': records.pop() elif attack=='extra': records.append(deepcopy(records[-1])) elif attack=='reordered': records.reverse() elif attack=='last_invalid': records[2]['output']['unexpected']=True _reidentify_capture(records[2]) elif attack=='nested_type': records[1]['context']['bsep']['source_write']=0 _reidentify_capture(records[1]) with pytest.raises(ValueError): semantics.CapturedProvider(records,attempts,origin=origin) positive=semantics.CapturedProvider.from_origin(origin) assert positive.index==0 for record in positive.records: assert positive.respond(record['role'],record['context'])==record['output']
@pytest.mark.parametrize('attempt_index',[0,1,2,3]) @pytest.mark.parametrize('field,value',[('attempt',True),('status','ARBITRARY'),('role','other'),('model','other'), ('projection_ref','ews:wrong'),('elapsed_seconds',False),('response_model','other'),('usage',{}),('unexpected',True)]) def test_capture_all_attempts_are_bound(tmp_path,attempt_index,field,value): config,_=_capture_package(tmp_path,live=True) origin=semantics.load_capture_origin(**config) attempts=semantics.parse(origin.attempts_bytes) attempts[attempt_index][field]=value with pytest.raises(ValueError,match='capture_original_history_binding'): semantics.CapturedProvider(semantics.parse(origin.records_bytes),attempts,origin=origin)
@pytest.mark.parametrize('target,field,value',[ ('attempt','status','STARTED'),('attempt','role',roles.ROLES[1]),('attempt','model','other'), ('attempt','projection_ref','ews:wrong'),('attempt','error_type','Unknown'),('attempt','elapsed_seconds',True), ('attempt','usage',dict(prompt_token_count=True,candidates_token_count=3,total_token_count=14)), ('attempt','response_model','other'),('request','automatic_retries',0),('request','max_output_tokens',True), ('request','contents','{}'),('request','projection_ref','ews:wrong'),('request','unexpected',True), ('transport','attempt',True),('transport','role',roles.ROLES[1]),('transport','context',{}), ('transport','raw','{"needs":["browse"],"uncertainty":[]}'),('transport','unexpected',True)]) def test_capture_loader_checks_full_history_schema(tmp_path,target,field,value): config,material=_capture_package(tmp_path,live=True) if target=='attempt': material['private/budget/attempts.json'][0][field]=value else: material['private/budget/%s_01.json'%target][field]=value # A newly pinned malformed synthetic package must still fail structural checks. config['manifest_sha256']=_write_capture_package(config['original_return_root'],material) with pytest.raises(ValueError): semantics.load_capture_origin(**config)
@pytest.mark.parametrize('transport_index',[1,2,3,4]) @pytest.mark.parametrize('mutation',['none','missing','bool','wrong','extra']) def test_capture_historical_failure_preserves_all_transport_ordinals(tmp_path,transport_index,mutation): # Schema-only regression with the exact original key sets. Actual original # manifest-bound acceptance is separately exercised by the external helper. config,material=_capture_package(tmp_path,live=True) records=material[config['records_path']] attempts=material['private/budget/attempts.json'] attempts[0].pop('usage') attempts[0].pop('response_model') material.pop('private/budget/request_01.json') assert set(attempts[0])=={'attempt','elapsed_seconds','error_type','model','projection_ref','role','status'} assert attempts[0]['status']=='FAILED' and attempts[0]['attempt']==1 for index in (1,2,3,4): transport=material['private/budget/transport_%02d.json'%index] assert set(transport)=={'attempt','context','model','raw','role'} assert type(transport['attempt']) is int and transport['attempt']==index for index in (2,3,4): assert set(material['private/budget/request_%02d.json'%index])=={ 'automatic_retries','contents','max_output_tokens','model','projection_ref','role','system_instruction'} snapshot={name:c.canonical(value) for name,value in material.items()} semantics._validate_history(records,attempts,snapshot,'private/budget',legacy_failure=True) with pytest.raises(ValueError,match='capture_attempt_shape'): semantics._validate_history(records,attempts,snapshot,'private/budget',legacy_failure=False) if mutation!='none': changed=deepcopy(material) transport=changed['private/budget/transport_%02d.json'%transport_index] if mutation=='missing': transport.pop('attempt') elif mutation=='bool': transport['attempt']=True elif mutation=='wrong': transport['attempt']=transport_index+1 else: transport['unexpected']=True with pytest.raises(ValueError,match='capture_transport_(shape|attempt)'): semantics._validate_history(records,attempts,{name:c.canonical(value) for name,value in changed.items()}, 'private/budget',legacy_failure=True) semantics._validate_history(records,attempts,snapshot,'private/budget',legacy_failure=True)
def test_capture_origin_and_provider_snapshots_are_immutable(tmp_path): from dataclasses import FrozenInstanceError config,_=_capture_package(tmp_path,live=True) origin=semantics.load_capture_origin(**config) records=semantics.parse(origin.records_bytes) attempts=semantics.parse(origin.attempts_bytes) provider=semantics.CapturedProvider(records,attempts,origin=origin) expected=deepcopy(records) records[2]['output'].clear() attempts[0]['status']='ARBITRARY' provider.records[1]['output'].clear() provider.attempts.clear() with pytest.raises(FrozenInstanceError): origin.expected_mode='CONTROLLED_DETERMINISTIC' with pytest.raises(TypeError): origin.materials[0]=('replacement',b'{}') with pytest.raises(AttributeError): provider.records=[] # Subsequent disk mutation cannot change an already checked byte snapshot. (config['original_return_root']/config['records_path']).write_text('[]') for record in expected: output=provider.respond(record['role'],record['context']) assert output==record['output'] output.clear() assert provider.records==expected with pytest.raises(ValueError,match='capture_material_hash'): semantics.load_capture_origin(**config)
def test_capture_loader_requires_independent_mode_and_pin(tmp_path): config,material=_capture_package(tmp_path,live=True) with pytest.raises(TypeError): semantics.CapturedProvider(material[config['records_path']],material['private/budget/attempts.json']) with pytest.raises(ValueError,match='capture_loader_origin_required'): semantics.CapturedProvider([],[],origin={}) with pytest.raises(ValueError,match='capture_manifest_pin_mismatch'): semantics.load_capture_origin(**dict(config,manifest_sha256='0'*64)) with pytest.raises(ValueError,match='capture_expected_origin_mode'): semantics.load_capture_origin(**dict(config,expected_mode='CONTROLLED_DETERMINISTIC',attempts_path=None)) with pytest.raises(ValueError,match='capture_live_ledger_required'): semantics.load_capture_origin(**dict(config,attempts_path=None)) with pytest.raises(ValueError,match='capture_relative_path'): semantics.load_capture_origin(**dict(config,records_path='../semantic_captures.json')) manifest_path=config['original_return_root']/'MANIFEST.json' manifest=semantics.parse(manifest_path.read_bytes()) manifest[0]['bytes']=True data=c.canonical(manifest) manifest_path.write_bytes(data) with pytest.raises(ValueError,match='capture_manifest_inventory'): semantics.load_capture_origin(**dict(config,manifest_sha256=c.digest(data)))
@pytest.mark.parametrize('path',['private/budget/attempts.json','private/budget/request_01.json', 'private/budget/transport_01.json','private/budget/capture_03.json']) def test_capture_manifest_binds_all_side_evidence(tmp_path,path): config,_=_capture_package(tmp_path,live=True) (config['original_return_root']/path).write_text('{}') with pytest.raises(ValueError,match='capture_material_hash'): semantics.load_capture_origin(**config)
@pytest.mark.parametrize('attack',['extra','missing','symlink','authority','unknown_legacy_failure']) def test_capture_loader_rejects_inventory_and_authority(tmp_path,attack): config,material=_capture_package(tmp_path,live=True) root=config['original_return_root'] if attack=='extra': (root/'private/budget/capture_04.json').write_text('{}') elif attack=='missing': (root/'private/budget/request_01.json').unlink() elif attack=='symlink': path=root/'private/budget/transport_01.json' data=path.read_bytes() path.unlink() (tmp_path/'outside.json').write_bytes(data) path.symlink_to(tmp_path/'outside.json') elif attack=='authority': record=material[config['records_path']][2] record['context']['root_decision']=dict(decision='ACCEPT',permission=True) _reidentify_capture(record) config['manifest_sha256']=_write_capture_package(root,material) else: material['private/budget/attempts.json'][0].pop('usage') material['private/budget/attempts.json'][0].pop('response_model') config['manifest_sha256']=_write_capture_package(root,material) with pytest.raises(ValueError): semantics.load_capture_origin(**config)
def test_capture_historical_controlled_context_is_not_rebound(tmp_path): config,_=_capture_package(tmp_path,asset_binding=False) origin=semantics.load_capture_origin(**config) provider=semantics.CapturedProvider.from_origin(origin) record=provider.records[0] new_context=dict(record['context'],asset_inventory=[dict(asset='asset:1',sha256='a'*64)]) with pytest.raises(ValueError,match='capture_input_binding'): provider.respond(record['role'],new_context) assert provider.index==0 for record in provider.records: assert provider.respond(record['role'],record['context'])==record['output']
def test_capture_cli_source_only_and_historical_workspace_refusal(tmp_path,monkeypatch,capsys): from demo import run_ephemeral_workspace_v01 as cli config,_=_capture_package(tmp_path,asset_binding=False) def forbidden(*args,**kwargs): pytest.fail('source-only capture must not create a Workspace or fixtures') monkeypatch.setattr(cli,'Workspace',forbidden) monkeypatch.setattr(cli,'generate',forbidden) argv=['demo','--mode','captured','--original-return-root',str(config['original_return_root']), '--original-manifest-sha256',config['manifest_sha256'],'--replay-mode','controlled', '--original-records-path',config['records_path']] monkeypatch.setattr('sys.argv',argv+['--capture-source-only']) cli.main() report=json.loads(capsys.readouterr().out) assert report['roles']==3 and report['new_model_calls']==0 assert report['asset_binding']=='HISTORICAL_CONTEXT_WITHOUT_ASSET_INVENTORY' assert report['workspace_execution']=='NOT_PERFORMED' run_dir=tmp_path/'must_not_exist' monkeypatch.setattr('sys.argv',argv+['--run-dir',str(run_dir)]) with pytest.raises(ValueError,match='historical_capture_without_asset_inventory_source_only'): cli.main() assert not run_dir.exists()
def test_controlled_contrast_same_registry_actual_execution(tmp_path,assets): session=Workspace(tmp_path/'contrast',assets,c.REQUEST_B) try: assert session.contract['active_classes']==list(c.CLASSES[:4]) assert 'EXPOSURE' not in session.allowed and 'CROP' not in session.allowed session.command('OPEN') original=session.preview['sha256'] for op,value in [('EXPOSURE',5),('CROP','SQUARE')]: with pytest.raises(ValueError,match='operation_not_allowed'): session.command(op,value) session.command('NEXT') assert session.preview['sha256']!=original assert len(session.host.registry.action_packet_lifecycle_entries)==2 assert session.work_results[1].consumed_fields[0].disposition=='USED' assert len(session.host.completed_work)==4 finally: session.close('DECLINE_SAVE_END') assert not (session.directory/'output/selection.json').exists() assert session.report()['source_preserved'] and session.status=='CLOSED_SUCCESS' with pytest.raises(ValueError,match='workspace_not_current'): session.command('NEXT')
def test_current_root_save_revision_and_exact_one_sidecar(tmp_path,assets): session=Workspace(tmp_path/'save',assets) try: session.command('OPEN') session.command('SELECT',True) with pytest.raises(ValueError,match='save_approval_current'): session.command('SAVE','ews:approval:unissued') session.command('REQUEST_SAVE') previous=deepcopy(session.pending) old=session.approve(previous) session.command('RATE',5) with pytest.raises(ValueError,match='save_approval_current'): session.command('SAVE',old) with pytest.raises(ValueError,match='approval_candidate_changed'): session.approve(previous) session.command('REQUEST_SAVE') wrong=deepcopy(session.pending);wrong['slot']='foreign.json' with pytest.raises(ValueError,match='approval_candidate_changed'): session.approve(wrong) approval=session.approve(deepcopy(session.pending)) intended=deepcopy(session.pending) session.command('SAVE',approval) actual=(session.directory/'output/selection.json').read_bytes() assert c.digest(actual)==intended['bytes_sha256'] and json.loads(actual)==intended['content'] for ref in (approval,c.identity('approval',session.history[-1]['receipt'])): with pytest.raises(ValueError): session.command('SAVE',ref) assert list((session.directory/'output').iterdir())==[session.directory/'output/selection.json'] clock=session.source.sample() with pytest.raises(ValueError): hosts.dispatch_current_action_v01(session.host,packet_id=session.history[0]['packet_id'],task_id=session.id, expected_revision=session.host.revision-1,evaluation_time=clock.evaluation_time, evaluation_time_source=clock.evaluation_time_source,evaluation_context_id=clock.evaluation_context_id) assert all(record['root_decision']['decision']=='ACCEPT' for record in session.history) finally: session.close() assert session.report()['source_preserved'] and session.status=='CLOSED_SUCCESS'
def test_mixed_semantic_obligations_source_only(tmp_path,assets): from demo.ephemeral_workspace_fixtures_v01 import generate_media media=generate_media(tmp_path/'media') sessions=[] try: for label,request in (('mixed',c.REQUEST_MIXED),('speech',c.REQUEST_SPEECH),('photo',c.REQUEST_B)): s=Workspace(tmp_path/label,assets,request,media=media);sessions.append(s) assert len(s.captures)==3 and all(v['mode']=='CONTROLLED_DETERMINISTIC' for v in s.captures) assert not s.services and s.media_review is None mixed,speech,photo=sessions assert mixed.contract['media']['audio_policy']=='SILENT_CONTINUE' assert speech.contract['media']['audio_policy']=='REQUIRE_AUDIO' and speech.contract['media']['speech_review'] assert 'media' not in photo.contract and 'PLAY' not in photo.allowed and 'AudioSink' not in photo.contract['active_classes'] assert mixed.captures[2]['context']['obligations']==mixed.captures[1]['output'] class Conflict(roles.ControlledProvider): def respond(self,role,context): v=super().respond(role,context) if role==roles.ROLES[1]:v['audio_policy']='SILENT_CONTINUE' return v with pytest.raises(ValueError):Workspace(tmp_path/'conflict',assets,c.REQUEST_SPEECH,Conflict(),media=media) finally: for s in sessions:s.close()
def test_local_semantic_memory_real_descent_and_fresh_authority(tmp_path,assets): import sys from hedgehog.domains.ephemeral_workspace.semantic_adapter_v01 import LiveProvider from hedgehog.domains.ephemeral_workspace.memory_adapter_v01 import SemanticMemory,MemoryProvider,dependencies producer_calls=[] tool=4;event=sys.monitoring.events.PY_START sys.monitoring.use_tool_id(tool,'ews-memory-live-producer-observer') sys.monitoring.register_callback(tool,event,lambda *args:producer_calls.append('LIVE_PROVIDER_RESPOND')) sys.monitoring.set_local_events(tool,LiveProvider.respond.__code__,event) store=SemanticMemory(tmp_path/'durable_drs') cold=warm=None try: cold=Workspace(tmp_path/'cold',assets,c.REQUEST_B) dep=dependencies(cold);now=cold.source.sample().evaluation_time assert store.select(root=cold.root,request=cold.request,dependency=dep,now=now) is None record=store.remember(cold) assert store.select(root='root:ews:personal:foreign',request=cold.request,dependency=dep,now=now) is None assert store.select(root=cold.root,request=cold.request,dependency=dict(dep,policy='changed'),now=now) is None assert store.select(root=cold.root,request=cold.request,dependency=dep,now=now,policy='ews.changed.v01') is None assert store.select(root=cold.root,request=cold.request,dependency=dep,now=now+3601) is None provider=MemoryProvider(store) warm=Workspace(tmp_path/'warm',assets,c.REQUEST_B,provider,personal_root=cold.root) assert warm.host is not cold.host and warm.id!=cold.id and not warm.approvals and not warm.services assert warm.mode=='DRS_REUSE_CANDIDATE' and warm.memory_origin['record_id']==record assert warm.report()['semantic_drs']=='ACTUAL_CURRENT_CANDIDATE_DESCENT' assert warm.contract==cold.contract and warm.route_review[2].decision_id!=cold.route_review[2].decision_id warm.command('OPEN');warm.command('SELECT',True);warm.command('RATE',4) warm.command('REQUEST_SAVE');approval=warm.approve(warm.pending) warm.command('SAVE',approval) store.remember_saved(warm) before=(len(warm.executed),len(warm.services),c.digest((warm.directory/'output/selection.json').read_bytes())) info=store.select(root=warm.root,request=warm.request,dependency=dependencies(warm),now=warm.source.sample().evaluation_time,kind='saved_work') assert info[0]['sidecar_sha256']==warm.saved['sha256'] and info[0]['history_ref']==c.digest(warm.history) assert before==(len(warm.executed),len(warm.services),c.digest((warm.directory/'output/selection.json').read_bytes())) assert provider.calls==0 assert producer_calls==[] print('MEMORY_LIVE_PRODUCER_OBSERVED_CALLS=0') finally: sys.monitoring.set_local_events(tool,LiveProvider.respond.__code__,0) sys.monitoring.register_callback(tool,event,None);sys.monitoring.free_tool_id(tool) if warm:warm.close() if cold:cold.close()
def test_live_stage_extension_preserves_attempts_and_reserve(tmp_path): from hedgehog.domains.ephemeral_workspace.semantic_adapter_v01 import LiveStageBudget chains=dict(main=c.REQUEST_MIXED,contrast=c.REQUEST_B) budget=LiveStageBudget(tmp_path,chains) context=dict(request=c.REQUEST_MIXED) index=budget.reserve('main',roles.ROLES[0],context) budget.finish(index,dict(status='FAILED',attempt=1,role=roles.ROLES[0],model='unit-observer-no-transport', projection_ref=c.identity('semantic_projection',dict(role=roles.ROLES[0],input=context)),elapsed_seconds=0,error_type='ValueError')) before=json.loads(budget.path.read_bytes()) extended=LiveStageBudget(tmp_path,chains,transport_ceiling=50) after=json.loads(extended.path.read_bytes()) assert after['attempts']==before['attempts'] and after['policy_changes'][0]['previous']==before['policy'] assert after['policy_changes'][0]['attempts_preserved']==1 with pytest.raises(ValueError,match='live_stage_policy_changed'):LiveStageBudget(tmp_path,chains) with pytest.raises(ValueError,match='live_stage_finite_ceiling'):LiveStageBudget(tmp_path,chains,transport_ceiling=51) index=extended.reserve('main',roles.ROLES[0],context) with pytest.raises(ValueError,match='live_stage_incomplete_attempt'):extended.reserve('contrast',roles.ROLES[0],dict(request=c.REQUEST_B)) assert index==2
