@_dataclass(frozen=True) class LegacyDRSProjectionV01: projection_version: str projection_id: str source_family: str source_version: str source_identity: str source_hash: str target_semantic_address_id: str target_meaning_record_id: str | None projection_profile_version: str fields_preserved: tuple[str, ...] fields_synthesized: tuple[str, ...] fields_unavailable: tuple[str, ...] downgrade_restrictions: tuple[str, ...] projection_status: str answer_shortcut_eligible: bool reason_codes: tuple[str, ...] creates_authority: bool creates_permission: bool
def _strict_json_plain(value: object, seen: set[int] | None = None) -> object: if seen is None: seen = set() if value is None or type(value) in (bool, int, str): if type(value) is str: reason = _secret_reason(value) if reason: raise ValueError(reason) return value if type(value) is float: if not _math.isfinite(value): raise ValueError("drs_legacy_source_invalid") return value if type(value) is list: marker = id(value) if marker in seen: raise ValueError("drs_legacy_source_invalid") seen.add(marker) result = [_strict_json_plain(item, seen) for item in value] seen.remove(marker) return result if type(value) is tuple: marker = id(value) if marker in seen: raise ValueError("drs_legacy_source_invalid") seen.add(marker) result = [_strict_json_plain(item, seen) for item in value] seen.remove(marker) return result if type(value) is dict: marker = id(value) if marker in seen: raise ValueError("drs_legacy_source_invalid") seen.add(marker) result: dict[str, object] = {} for key, item in value.items(): if type(key) is not str: raise ValueError("drs_legacy_source_invalid") result[key] = _strict_json_plain(item, seen) seen.remove(marker) return result raise ValueError("drs_legacy_source_invalid")
def _fail() -> None: raise ValueError("drs_legacy_source_invalid")
def _exact_dict_keys( value: object, *, required: tuple[str, ...], allowed: tuple[str, ...], ) -> dict[str, object]: if type(value) is not dict or any(type(key) is not str for key in value): _fail() if any(name not in value for name in required): _fail() if any(name not in allowed for name in value): _fail() return value
def _legacy_id(value: object) -> bool: return ( type(value) is str and _LEGACY_ID.fullmatch(value) is not None and _secret_reason(value) is None )
def _nonempty_text(value: object) -> bool: return ( type(value) is str and bool(value) and len(value) <= 1024 and _secret_reason(value) is None )
def _rfc3339(value: object, *, allow_none: bool = False) -> bool: return ( value is None if allow_none else False ) or ( type(value) is str and _RFC3339.fullmatch(value) is not None and _secret_reason(value) is None )
def _exact_string_sequence( value: object, *, container_type: type, references: bool = True, ) -> bool: if type(value) is not container_type: return False predicate = _legacy_id if references else _nonempty_text return all(predicate(item) for item in value)
def _exact_dataclass_fields(value: object, expected: tuple[str, ...]) -> bool: try: return tuple(field.name for field in _dataclass_fields(type(value))) == expected except (TypeError, AttributeError): return False
def _validate_trace_ref(value: object) -> None: mapping = _exact_dict_keys( value, required=("trace_id",), allowed=("trace_id", "span_id", "kind"), ) if not _legacy_id(mapping["trace_id"]): _fail() if "span_id" in mapping and not _legacy_id(mapping["span_id"]): _fail() if "kind" in mapping and not _nonempty_text(mapping["kind"]): _fail()
def _validate_source_ref(value: object) -> None: mapping = _exact_dict_keys( value, required=("source",), allowed=("source", "source_id", "trace_ref"), ) if mapping["source"] not in ( "user", "system", "needle", "local_drs", "external_drs", "fallback", "executor", "validator", ): _fail() if "source_id" in mapping and not _legacy_id(mapping["source_id"]): _fail() if "trace_ref" in mapping: _validate_trace_ref(mapping["trace_ref"])
