def _build_decision( firewall: EffectFirewallV01, request: EffectRequestV01, tick: int, decision: str, reason: str, capability_id: str | None, capability_issued: bool, return_to_root: bool, ) -> EffectFirewallDecisionV01: return _build_decision_values_v01( firewall_id=firewall.firewall_id, invocation_id=firewall.invocation_id, request=request, tick=tick, decision=decision, reason=reason, capability_id=capability_id, capability_issued=capability_issued, return_to_root=return_to_root, )
def _build_decision_values_v01( *, firewall_id: str, invocation_id: str, request: EffectRequestV01, tick: int, decision: str, reason: str, capability_id: str | None, capability_issued: bool, return_to_root: bool, ) -> EffectFirewallDecisionV01: provisional = EffectFirewallDecisionV01( decision_id="0" * 64, firewall_id=firewall_id, invocation_id=invocation_id, request_id=request.request_id, transaction_id=request.transaction_id, target_root_id=request.target_root_id, root_decision_id=request.root_decision_id, adapter_id=request.adapter_id, action_kind=request.action_kind, evaluated_at_tick=tick, decision=decision, reason_code=reason, capability_id=capability_id, capability_issued=capability_issued, return_to_root=return_to_root, real_world_effects_count=0, ) return EffectFirewallDecisionV01( decision_id=_decision_id(provisional), firewall_id=provisional.firewall_id, invocation_id=provisional.invocation_id, request_id=provisional.request_id, transaction_id=provisional.transaction_id, target_root_id=provisional.target_root_id, root_decision_id=provisional.root_decision_id, adapter_id=provisional.adapter_id, action_kind=provisional.action_kind, evaluated_at_tick=tick, decision=decision, reason_code=reason, capability_id=capability_id, capability_issued=capability_issued, return_to_root=return_to_root, real_world_effects_count=0, )
def _decision_structure_errors(decision: object) -> tuple[str, ...]: if type(decision) is not EffectFirewallDecisionV01: return ("effect_firewall_decision_invalid",) errors: list[str] = [] if not all( _valid_text(value) for value in ( decision.decision_id, decision.firewall_id, decision.invocation_id, decision.request_id, decision.transaction_id, decision.target_root_id, decision.root_decision_id, decision.adapter_id, decision.action_kind, decision.reason_code, ) ) or type(decision.evaluated_at_tick) is not int or decision.evaluated_at_tick < 0: errors.append("effect_firewall_decision_invalid") if type(decision.decision) is not str or decision.decision not in EFFECT_FIREWALL_DECISIONS: errors.append("effect_firewall_decision_invalid") if decision.decision == EFFECT_DECISION_ALLOW_MOCK_EFFECT: if ( decision.reason_code != "mock_effect_authorized" or not _valid_sha256(decision.capability_id) or decision.capability_issued is not True or decision.return_to_root is not False ): errors.append("effect_firewall_reason_mismatch") elif ( decision.reason_code not in _BLOCK_REASONS or decision.capability_id is not None or decision.capability_issued is not False or decision.return_to_root is not True ): errors.append("effect_firewall_reason_mismatch") if type(decision.real_world_effects_count) is not int or decision.real_world_effects_count != 0: errors.append("effect_firewall_decision_invalid") if not errors: try: if decision.decision_id != _decision_id(decision): errors.append("effect_firewall_decision_id_mismatch") except Exception: errors.append("effect_firewall_decision_id_mismatch") return _dedupe(errors)
def _firewall_plain( firewall: EffectFirewallV01, *, include_id: bool = True, ) -> dict[str, object]: projected: dict[str, object] = { "firewall_version": firewall.firewall_version, "invocation_id": firewall.invocation_id, "transaction_id": firewall.transaction_id, "target_root_id": firewall.target_root_id, "root_decision_id": firewall.root_decision_id, "selected_candidate_id": firewall.selected_candidate_id, "permission_ref": firewall.permission_ref, "allowed_adapter_ids": list(firewall.allowed_adapter_ids), "allowed_action_kinds": list(firewall.allowed_action_kinds), "root_scope_refs": list(firewall.root_scope_refs), "maximum_expires_at_tick": firewall.maximum_expires_at_tick, "mock_only": firewall.mock_only, "effect_access_owner": firewall.effect_access_owner, } if include_id: return {"firewall_id": firewall.firewall_id, **projected} return projected
def _request_plain(request: EffectRequestV01) -> dict[str, object]: return { "request_id": request.request_id, "request_kind": request.request_kind, "transaction_id": request.transaction_id, "target_root_id": request.target_root_id, "root_decision_id": request.root_decision_id, "selected_candidate_id": request.selected_candidate_id, "permission_ref": request.permission_ref, "adapter_id": request.adapter_id, "action_kind": request.action_kind, "scope_refs": list(request.scope_refs), "issued_at_tick": request.issued_at_tick, "expires_at_tick": request.expires_at_tick, "idempotency_key": request.idempotency_key, "mock_only": request.mock_only, }
def _decision_plain(decision: EffectFirewallDecisionV01) -> dict[str, object]: return { "decision_id": decision.decision_id, "firewall_id": decision.firewall_id, "invocation_id": decision.invocation_id, "request_id": decision.request_id, "transaction_id": decision.transaction_id, "target_root_id": decision.target_root_id, "root_decision_id": decision.root_decision_id, "adapter_id": decision.adapter_id, "action_kind": decision.action_kind, "evaluated_at_tick": decision.evaluated_at_tick, "decision": decision.decision, "reason_code": decision.reason_code, "capability_id": decision.capability_id, "capability_issued": decision.capability_issued, "return_to_root": decision.return_to_root, "real_world_effects_count": decision.real_world_effects_count, }
def _request_id(request: EffectRequestV01) -> str: material = _request_plain(request) material.pop("request_id") return _hash(_REQUEST_DOMAIN, material)
def _decision_id(decision: EffectFirewallDecisionV01) -> str: material = _decision_plain(decision) material.pop("decision_id") return _hash(_DECISION_DOMAIN, material)
def _hash(domain: str, value: object) -> str: return _domain_separated_sha256_hex_v01( domain=domain, payload=_canonical_json_bytes_v01(value), )
def _valid_text(value: object) -> bool: if type(value) is not str or not value: return False try: _canonical_json_bytes_v01(value) return True except Exception: return False
def _valid_sha256(value: object) -> bool: return bool( type(value) is str and len(value) == 64 and all(character in "0123456789abcdef" for character in value) )
def _valid_text_tuple(value: object, *, allow_empty: bool) -> bool: return bool( type(value) is tuple and (allow_empty or value) and all(_valid_text(item) for item in value) and len(value) == len(set(value)) )
def _valid_text_list(value: object, *, allow_empty: bool) -> bool: return bool( type(value) is list and (allow_empty or value) and all(_valid_text(item) for item in value) and len(value) == len(set(value)) )
def _is_subset(child: tuple[str, ...], parent: tuple[str, ...]) -> bool: return all(item in parent for item in child)
def _allowed_reason(error: ValueError, allowed: tuple[str, ...]) -> str | None: if len(error.args) == 1 and type(error.args[0]) is str and error.args[0] in allowed: return error.args[0] return None
def _dedupe(values: object) -> tuple[str, ...]: return tuple(dict.fromkeys(values))
# Native capability definitions are inert during module initialization. Nominal action value # access occurs only after both modules have completed initialization. @_dataclass(frozen=True) class CapabilityFieldV01: name: str value_type: str required: bool consequential: bool minimum: int | str | None maximum: int | str | None allowed_values: tuple[str | int | bool, ...]
