_NATIVE_TYPES = (CapabilityFieldV01, CapabilityBusinessInputBindingV01, CapabilityBusinessSemanticsV01, CapabilityDefinitionV01, CapabilityCodeSnapshotV01, CapabilityAdmissionSnapshotV01, CapabilityValidationEvidenceV01, BoundCapabilityInvocationV01, CapabilityExecutionResultV01, NativeExecutionEvidenceV01) _NATIVE_CONTROL_NAMES = ('capability_definition_ref', 'capability_implementation_ref', 'capability_input_contract_ref', 'capability_output_contract_ref') _NATIVE_RECEIPT_PROFILE = 'common_action.execution_result.v01' _NATIVE_RECEIPT_KEYS = tuple(sorted((*_RECEIPT_PAYLOAD_KEYS, 'receipt_profile', 'execution_evidence')))
def _native_require(condition: bool, reason: str) -> None: if not condition: raise ValueError(reason)
def _native_value(value: object) -> object: from hedgehog import action_commit_packet_v02 as action if value is None: return action.ABSENT_V01 if type(value) in (str, int, bool): return value if type(value) is action.ActionEffectParameterRecordV01: _native_require(action.validate_action_effect_parameter_record_v01(value)[0], 'capability_record_invalid') return action.action_effect_parameter_record_material_v01(value) if type(value) in _NATIVE_TYPES: return tuple((f.name, _native_value(getattr(value, f.name))) for f in _fields(value)) if type(value) is tuple: return tuple(_native_value(v) for v in value) raise ValueError('capability_material_type_invalid')
def _native_material(value: object, excluded: tuple[str, ...] = ()) -> tuple: return tuple((f.name, _native_value(getattr(value, f.name))) for f in _fields(value) if f.name not in excluded)
def _native_identity(leaf: str, material: tuple, prefix: str | None = None) -> str: from hedgehog import action_commit_packet_v02 as action if prefix == '': return action.domain_separated_sha256_hex_v01(domain='hedgehog.common_action.'+leaf+'.v01', payload=action.canonical_material_bytes_v01(material)) return action.build_domain_separated_identity_v01(domain='hedgehog.common_action.'+leaf+'.v01', prefix=leaf+':' if prefix is None else prefix, material=material)
def capability_value_subject_sha256_v01(values: object) -> str: from hedgehog import action_commit_packet_v02 as action _native_require(type(values) is tuple, 'capability_values_type') for value in values: _native_require(type(value) is action.ActionEffectParameterRecordV01 and action.validate_action_effect_parameter_record_v01(value)[0], 'capability_record_invalid') return _native_identity('capability_value_subject', (('records', _native_value(values)),), '')
def _capability_scalar_valid(kind: str, value: object) -> bool: from hedgehog import action_commit_packet_v02 as action if kind in ('TEXT', 'REFERENCE'): return type(value) is str and action.validate_identity_text_v01(value)[0] if kind == 'DECIMAL': return type(value) is str and action.validate_canonical_decimal_v01(value)[0] if kind == 'INTEGER': return type(value) is int and action.validate_signed_int64_v01(value)[0] return kind == 'BOOLEAN' and type(value) is bool
def validate_capability_field_v01(value: object) -> tuple[str, ...]: try: _native_require(type(value) is CapabilityFieldV01 and _valid_text(value.name), 'capability_field_type') _native_require(value.name not in _NATIVE_CONTROL_NAMES, 'capability_reserved_field') _native_require(value.value_type in ('TEXT', 'REFERENCE', 'DECIMAL', 'INTEGER', 'BOOLEAN') and type(value.required) is type(value.consequential) is bool, 'capability_field_declaration') _native_require(type(value.allowed_values) is tuple and len({(type(v), v) for v in value.allowed_values})==len(value.allowed_values), 'capability_allowed_values') _native_require(all(_capability_scalar_valid(value.value_type, v) for v in value.allowed_values), 'capability_allowed_value_type') for bound in (value.minimum, value.maximum): _native_require(bound is None or value.value_type in ('DECIMAL', 'INTEGER') and _capability_scalar_valid(value.value_type, bound), 'capability_field_range_type') if value.minimum is not None and value.maximum is not None: from decimal import Decimal _native_require(Decimal(value.minimum)<=Decimal(value.maximum), 'capability_field_range') return () except (ValueError, TypeError, AttributeError) as exc: return (str(exc) if type(exc) is ValueError else 'capability_field_invalid',)
def build_capability_field_v01(*, name: str, value_type: str, required: bool, consequential: bool, minimum: object = None, maximum: object = None, allowed_values: tuple = ()) -> CapabilityFieldV01: value=CapabilityFieldV01(name,value_type,required,consequential,minimum,maximum,allowed_values) errors=validate_capability_field_v01(value) if errors:raise ValueError(errors[0]) return value
def _capability_fields_valid(values: object) -> bool: return (type(values) is tuple and all(not validate_capability_field_v01(v) for v in values) and tuple(v.name for v in values)==tuple(sorted({v.name for v in values})))
def validate_capability_values_v01(fields: object, values: object) -> tuple[str, ...]: from hedgehog import action_commit_packet_v02 as action try: _native_require(_capability_fields_valid(fields) and type(values) is tuple, 'capability_value_shape') _native_require(all(type(v) is action.ActionEffectParameterRecordV01 and action.validate_action_effect_parameter_record_v01(v)[0] for v in values), 'capability_record_invalid') names=tuple(v.parameter_name for v in values) _native_require(names==tuple(sorted(set(names))) and set(names)<=set(f.name for f in fields), 'capability_value_names') actual={v.parameter_name:v for v in values} for f in fields: _native_require(not f.required or f.name in actual,'capability_value_missing:'+f.name) if f.name not in actual:continue v=actual[f.name] _native_require(v.value_type==f.value_type and _capability_scalar_valid(f.value_type,v.value),'capability_value_type:'+f.name) _native_require(not f.allowed_values or (type(v.value),v.value) in {(type(x),x) for x in f.allowed_values},'capability_value_not_allowed:'+f.name) from decimal import Decimal _native_require(f.minimum is None or Decimal(v.value)>=Decimal(f.minimum),'capability_value_below_minimum:'+f.name) _native_require(f.maximum is None or Decimal(v.value)<=Decimal(f.maximum),'capability_value_above_maximum:'+f.name) return () except (ValueError, TypeError, AttributeError) as exc: return (str(exc) if type(exc) is ValueError else 'capability_values_invalid',)
def build_capability_business_input_binding_v01(*, input_name: str, source_kind: str, source_name: str, value_type: str) -> CapabilityBusinessInputBindingV01: value=CapabilityBusinessInputBindingV01(input_name,source_kind,source_name,value_type) _native_require(all(_valid_text(x) for x in (input_name,source_kind,source_name,value_type)), 'capability_business_binding_text') _native_require(input_name not in _NATIVE_CONTROL_NAMES and source_name not in _NATIVE_CONTROL_NAMES, 'capability_reserved_field') scalars={'AMOUNT':('amount_decimal','DECIMAL'),'CURRENCY':('currency_code','TEXT'), 'QUANTITY':('quantity_decimal','DECIMAL'),'BUSINESS_OBJECT_REF':('business_object_ref','REFERENCE')} _native_require(source_kind in (*scalars,'RECORD','SUBJECT_RECORD','TARGET_RECORD'), 'capability_business_source_kind') _native_require(source_kind not in scalars or (source_name,value_type)==scalars[source_kind], 'capability_business_scalar_selector') _native_require(source_kind not in ('SUBJECT_RECORD','TARGET_RECORD') or value_type=='REFERENCE', 'capability_business_scope_type') return value
def build_capability_business_semantics_v01(*, operation_key: str, selected_action_class: str, logical_effect_class: str, logical_effect_namespace: str, business_object_class: str, business_object_namespace: str, input_bindings: tuple) -> CapabilityBusinessSemanticsV01: _native_require(all(_valid_text(x) for x in (operation_key,selected_action_class,logical_effect_class,logical_effect_namespace,business_object_class,business_object_namespace)), 'capability_business_text') _native_require(operation_key==logical_effect_namespace and selected_action_class.startswith(MOCK_ACTION_PREFIX), 'capability_business_operation') _native_require(type(input_bindings) is tuple and all(type(v) is CapabilityBusinessInputBindingV01 for v in input_bindings), 'capability_business_bindings_type') for value in input_bindings: _native_require(build_capability_business_input_binding_v01(**{f.name:getattr(value,f.name) for f in _fields(value)})==value, 'capability_business_binding') bindings=tuple(sorted(input_bindings,key=lambda v:v.input_name)) _native_require(len({v.input_name for v in bindings})==len(bindings), 'capability_business_binding_duplicate') return CapabilityBusinessSemanticsV01(operation_key,selected_action_class,logical_effect_class,logical_effect_namespace,business_object_class,business_object_namespace,bindings)
