def validate_capability_definition_v01(value: object) -> tuple[str, ...]: try: _native_require(type(value) is CapabilityDefinitionV01, 'capability_definition_type') _native_require(all(_valid_text(getattr(value,n)) for n in ('definition_id','operation_id','version','input_validator_ref','output_validator_ref','executor_ref')), 'capability_definition_text') _native_require(value.effect_kind in ('PURE','MOCK_CONSEQUENTIAL'), 'capability_effect_kind') _native_require(_capability_fields_valid(value.input_fields) and _capability_fields_valid(value.output_fields), 'capability_definition_fields') _native_require(_valid_text_tuple(value.resource_refs,allow_empty=True) and value.resource_refs==tuple(sorted(value.resource_refs)), 'capability_resources') if value.effect_kind=='PURE': _native_require(value.business_semantics is None and not any(f.consequential for f in value.input_fields), 'capability_pure_semantics') else: semantics=value.business_semantics _native_require(type(semantics) is CapabilityBusinessSemanticsV01, 'capability_business_type') _native_require(build_capability_business_semantics_v01(**{f.name:getattr(semantics,f.name) for f in _fields(semantics)})==semantics, 'capability_business_semantics') _native_require(value.operation_id==semantics.operation_key and tuple(v.input_name for v in semantics.input_bindings)==tuple(f.name for f in value.input_fields) and all(f.required and f.consequential and f.value_type==b.value_type for f,b in zip(value.input_fields,semantics.input_bindings)), 'capability_business_exhaustive_mapping') _native_require(type(value.code_sha256s) is tuple and all(type(p) is tuple and len(p)==2 and _valid_text(p[0]) and _valid_sha256(p[1]) for p in value.code_sha256s), 'capability_code_hashes') _native_require(tuple(p[0] for p in value.code_sha256s)==tuple(sorted({value.input_validator_ref,value.output_validator_ref,value.executor_ref})) and len(value.code_sha256s)==3,'capability_code_symbols') i,o=_capability_contract_refs(value) _native_require(value.contract_sha256==_native_identity('capability_contract',(('input_contract_ref',i),('output_contract_ref',o)),''), 'capability_contract_hash') _native_require(value.definition_id==_native_identity('capability_definition',_native_material(value,('definition_id',))), 'capability_definition_identity') return () except (ValueError, KeyError, TypeError, AttributeError) as exc: return (str(exc) if type(exc) is ValueError else 'capability_definition_invalid',)
def build_capability_definition_v01(*, operation_id: str, version: str, effect_kind: str, business_semantics: object, input_fields: tuple, output_fields: tuple, resource_refs: tuple, input_validator_ref: str, output_validator_ref: str, executor_ref: str, code_sha256s: tuple) -> CapabilityDefinitionV01: value=CapabilityDefinitionV01('',operation_id,version,effect_kind,business_semantics, tuple(sorted(input_fields,key=lambda v:v.name)),tuple(sorted(output_fields,key=lambda v:v.name)), tuple(sorted(resource_refs)),input_validator_ref,output_validator_ref,executor_ref,tuple(sorted(code_sha256s)),'') i,o=_capability_contract_refs(value) value=_replace(value,contract_sha256=_native_identity('capability_contract',(('input_contract_ref',i),('output_contract_ref',o)),'')) value=_replace(value,definition_id=_native_identity('capability_definition',_native_material(value,('definition_id',)))) errors=validate_capability_definition_v01(value) if errors:raise ValueError(errors[0]) return value
