def build_semantic_work_request_v01( *, request_id: str, transaction_id: str, target_root_id: str, runtime_topology_ref: str, bounded_context_refs: tuple[str, ...], permitted_actor_ids: tuple[str, ...], permitted_contribution_modes: tuple[str, ...], requested_subjects: tuple[str, ...], required_evidence_classes: tuple[str, ...], forbidden_claims: tuple[str, ...], ) -> SemanticWorkRequestV01: request = SemanticWorkRequestV01( request_id=request_id, transaction_id=transaction_id, target_root_id=target_root_id, runtime_topology_ref=runtime_topology_ref, bounded_context_refs=bounded_context_refs, permitted_actor_ids=permitted_actor_ids, permitted_contribution_modes=permitted_contribution_modes, requested_subjects=requested_subjects, required_evidence_classes=required_evidence_classes, forbidden_claims=forbidden_claims, ) errors = validate_semantic_work_request_v01(request) if errors: raise ValueError(errors[0]) from None return request
def build_evidence_binding_v01( *, evidence_id: str, evidence_ref: str, evidence_class: str, source_component_id: str, provenance_ref: str, evidence_state: str, ) -> EvidenceBindingV01: try: binding = EvidenceBindingV01( evidence_id=evidence_id, evidence_ref=evidence_ref, evidence_class=evidence_class, source_component_id=source_component_id, provenance_ref=provenance_ref, evidence_state=evidence_state, ) if _evidence_errors(binding): raise ValueError("evidence_binding_invalid") return binding except Exception: raise ValueError("evidence_binding_invalid") from None
