def _valid_text(value: object) -> bool: return bool( type(value) is str and value and not any(0xD800 <= ord(character) <= 0xDFFF for character in value) )
def _valid_text_tuple(value: object, *, allow_empty: bool = False) -> bool: return bool( type(value) is tuple and (allow_empty or bool(value)) and all(_valid_text(item) for item in value) and len(value) == len(set(value)) )
