def _freeze_json_value(value: object) -> object: frozen = _freeze_json_snapshot(value, set()) if not _frozen_json_valid(frozen): raise ValueError("json_value_invalid") return frozen
def _freeze_json_snapshot(value: object, active: set[int]) -> object: if value is None or type(value) in {bool, int, float, str}: return value identity = id(value) if identity in active: raise ValueError("json_cycle_invalid") active.add(identity) try: if type(value) in {tuple, list}: return tuple(_freeze_json_snapshot(item, active) for item in value) if isinstance(value, _Mapping): frozen_rows: list[tuple[str, object]] = [] observed_keys: set[str] = set() rows = value.items() for row in rows: if type(row) is not tuple or len(row) != 2: raise ValueError("json_mapping_invalid") key, item = row if type(key) is not str: raise ValueError("json_mapping_invalid") if key in observed_keys: raise ValueError("json_mapping_duplicate_key") observed_keys.add(key) frozen_rows.append((key, _freeze_json_snapshot(item, active))) frozen_rows.sort(key=lambda row: row[0]) return _FrozenJSONObject(tuple(frozen_rows)) raise ValueError("json_value_invalid") finally: active.remove(identity)
def _thaw_json_value(value: object) -> object: if not _frozen_json_structure_valid(value, set()): raise ValueError("frozen_json_invalid") thawed = _thaw_json_validated(value) _canonical_json_bytes_v01(thawed) return thawed
def _thaw_json_validated(value: object) -> object: if type(value) is _FrozenJSONObject: return {key: _thaw_json_validated(item) for key, item in value.items} if type(value) is tuple: return [_thaw_json_validated(item) for item in value] if value is None or type(value) in {bool, int, float, str}: return value raise ValueError("frozen_json_invalid")
def _frozen_json_structure_valid(value: object, active: set[int]) -> bool: if value is None or type(value) in {bool, int, float, str}: return True if type(value) not in {tuple, _FrozenJSONObject}: return False identity = id(value) if identity in active: return False active.add(identity) try: if type(value) is tuple: return all(_frozen_json_structure_valid(item, active) for item in value) if type(value.items) is not tuple: return False keys: list[str] = [] for row in value.items: if type(row) is not tuple or len(row) != 2: return False key, item = row if type(key) is not str: return False keys.append(key) if not _frozen_json_structure_valid(item, active): return False return keys == sorted(keys) and len(keys) == len(set(keys)) finally: active.remove(identity)
