def _contribution_contract_errors( contribution: object, ) -> tuple[str, ...]: if type(contribution) is not ActorContributionV01: return ("actor_contribution_invalid",) errors: list[str] = [] if not all( _valid_text(value) for value in ( contribution.contribution_id, contribution.request_id, contribution.actor_id, contribution.actor_role, contribution.contribution_mode, contribution.bsep_projection_ref, contribution.scope, ) ): errors.append("actor_contribution_invalid") if ( type(contribution.contribution_mode) is not str or contribution.contribution_mode not in CONTRIBUTION_MODES ): errors.append("contribution_mode_unknown") elif contribution.actor_role != _MODE_ROLE_MAP[contribution.contribution_mode]: errors.append("contribution_mode_role_mismatch") if not _valid_text_tuple(contribution.bounded_context_refs): errors.append("bounded_context_violation") nested_checks = ( (contribution.claims, NormalizedClaimV01, False, "claim_contract_invalid"), ( contribution.evidence_bindings, EvidenceBindingV01, False, "evidence_binding_invalid", ), ( contribution.constraint_bindings, ConstraintBindingV01, True, "constraint_binding_invalid", ), ( contribution.uncertainty_bindings, UncertaintyBindingV01, True, "uncertainty_binding_invalid", ), ) for value, expected_type, allow_empty, reason in nested_checks: if type(value) is not tuple or (not allow_empty and not value) or any( type(item) is not expected_type for item in value ): errors.append(reason) if type(contribution.claims) is tuple: for claim in contribution.claims: errors.extend(_claim_errors(claim)) if type(claim) is NormalizedClaimV01: if claim.source_role != contribution.actor_role: errors.append("actor_role_invalid") if claim.source_mode != contribution.contribution_mode: errors.append("contribution_mode_role_mismatch") if type(contribution.evidence_bindings) is tuple: for binding in contribution.evidence_bindings: errors.extend(_evidence_errors(binding)) if type(contribution.constraint_bindings) is tuple: for binding in contribution.constraint_bindings: errors.extend(_constraint_errors(binding)) if type(contribution.uncertainty_bindings) is tuple: for binding in contribution.uncertainty_bindings: errors.extend(_uncertainty_errors(binding)) if not _valid_text_tuple(contribution.requested_validators, allow_empty=True): errors.append("requested_validator_invalid") if not _valid_text_tuple( contribution.forbidden_claims_observed, allow_empty=True ): errors.append("actor_contribution_invalid") if contribution.forbidden_claims_observed: errors.append("forbidden_claim_observed") if type(contribution.evidence_bindings) is tuple: evidence_ids = tuple(item.evidence_id for item in contribution.evidence_bindings) if len(evidence_ids) != len(set(evidence_ids)): errors.append("evidence_binding_invalid") evidence_by_id = { item.evidence_id: item for item in contribution.evidence_bindings } if type(contribution.claims) is tuple: for claim in contribution.claims: if type(claim) is not NormalizedClaimV01: continue for evidence_id in claim.evidence_refs: binding = evidence_by_id.get(evidence_id) if binding is None or binding.evidence_state == EVIDENCE_STATE_REJECTED: errors.append("evidence_ref_unbound") for values, reason in ( (contribution.constraint_bindings, "constraint_binding_invalid"), (contribution.uncertainty_bindings, "uncertainty_binding_invalid"), ): if type(values) is tuple: ids = tuple( item.constraint_id if type(item) is ConstraintBindingV01 else item.uncertainty_id for item in values ) if len(ids) != len(set(ids)): errors.append(reason) if type(contribution.uncertainty_bindings) is tuple and type( contribution.claims ) is tuple: claim_ids = {item.claim_id for item in contribution.claims} if any( item.claim_id not in claim_ids for item in contribution.uncertainty_bindings if type(item) is UncertaintyBindingV01 ): errors.append("uncertainty_claim_ref_invalid") return tuple(dict.fromkeys(errors))
def _build_packet_from_validated( request: SemanticWorkRequestV01, contributions: tuple[ActorContributionV01, ...], ) -> RootReviewPacketV01: claims: list[NormalizedClaimV01] = [] claim_identity_by_id: dict[str, bytes] = {} observed_claim_identities: set[bytes] = set() for contribution in contributions: for claim in contribution.claims: identity = _canonical_claim_bytes(claim) existing_identity = claim_identity_by_id.get(claim.claim_id) if existing_identity is not None and existing_identity != identity: raise ValueError("claim_contract_invalid") if existing_identity is None: claim_identity_by_id[claim.claim_id] = identity if identity not in observed_claim_identities: observed_claim_identities.add(identity) claims.append(claim) normalized_claims = tuple(claims) conflict_sets = _build_conflict_sets(normalized_claims) missing_refs: list[str] = [] validators: list[str] = [] for contribution in contributions: for binding in contribution.evidence_bindings: if ( binding.evidence_state == EVIDENCE_STATE_MISSING and binding.evidence_ref not in missing_refs ): missing_refs.append(binding.evidence_ref) for validator in contribution.requested_validators: if validator not in validators: validators.append(validator) modes = tuple( mode for mode in CONTRIBUTION_MODES if any(item.contribution_mode == mode for item in contributions) ) if conflict_sets and missing_refs: summary = "advisory_claims_with_visible_conflicts_and_missing_evidence" elif conflict_sets: summary = "advisory_claims_with_visible_conflicts" elif missing_refs: summary = "advisory_claims_with_missing_evidence" else: summary = "advisory_claims_ready_for_root_review" proposal_without_id = { "request_id": request.request_id, "source_contribution_ids": [item.contribution_id for item in contributions], "normalized_claims": [_claim_plain(item) for item in normalized_claims], "conflict_sets": [_conflict_plain(item) for item in conflict_sets], "missing_evidence_refs": list(missing_refs), "contribution_modes": list(modes), "requested_validators": list(validators), "synthesis_summary": summary, "authority_class": SYNTHESIS_AUTHORITY_ADVISORY, "root_review_required": True, } proposal_id = _domain_separated_sha256_hex_v01( domain=_SYNTHESIS_DOMAIN, payload=_canonical_json_bytes_v01(proposal_without_id), ) proposal = SynthesisProposalV01( proposal_id=proposal_id, request_id=request.request_id, source_contribution_ids=tuple(item.contribution_id for item in contributions), normalized_claims=normalized_claims, conflict_sets=conflict_sets, missing_evidence_refs=tuple(missing_refs), contribution_modes=modes, requested_validators=tuple(validators), synthesis_summary=summary, authority_class=SYNTHESIS_AUTHORITY_ADVISORY, root_review_required=True, ) packet_without_id = { "request_id": request.request_id, "transaction_id": request.transaction_id, "target_root_id": request.target_root_id, "runtime_topology_ref": request.runtime_topology_ref, "synthesis_proposal": _synthesis_plain(proposal), "contribution_ids": [item.contribution_id for item in contributions], "conflict_set_ids": [item.conflict_set_id for item in conflict_sets], "missing_evidence_refs": list(missing_refs), "required_validator_ids": list(validators), "review_state": ROOT_REVIEW_STATE, "authority_class": SYNTHESIS_AUTHORITY_ADVISORY, "root_decision_created": False, "permission_created": False, "final_output_created": False, } packet_id = _domain_separated_sha256_hex_v01( domain=_PACKET_DOMAIN, payload=_canonical_json_bytes_v01(packet_without_id), ) return RootReviewPacketV01( packet_id=packet_id, request_id=request.request_id, transaction_id=request.transaction_id, target_root_id=request.target_root_id, runtime_topology_ref=request.runtime_topology_ref, synthesis_proposal=proposal, contribution_ids=tuple(item.contribution_id for item in contributions), conflict_set_ids=tuple(item.conflict_set_id for item in conflict_sets), missing_evidence_refs=tuple(missing_refs), required_validator_ids=tuple(validators), review_state=ROOT_REVIEW_STATE, authority_class=SYNTHESIS_AUTHORITY_ADVISORY, root_decision_created=False, permission_created=False, final_output_created=False, )
def _build_conflict_sets( claims: tuple[NormalizedClaimV01, ...], ) -> tuple[ConflictSetV01, ...]: groups: dict[tuple[str, str, str], list[NormalizedClaimV01]] = {} for claim in claims: key = (claim.subject, claim.predicate, claim.time_envelope_ref) groups.setdefault(key, []).append(claim) conflicts: list[ConflictSetV01] = [] for (subject, predicate, _time_ref), grouped in groups.items(): value_bytes = tuple( _canonical_json_bytes_v01(_thaw_json_value(item.object_or_value)) for item in grouped ) if len(set(value_bytes)) < 2: continue claim_ids = tuple(item.claim_id for item in grouped) conflicting_values = tuple(item.object_or_value for item in grouped) source_modes = tuple(item.source_mode for item in grouped) material = _conflict_hash_material( subject=subject, predicate=predicate, claim_ids=claim_ids, conflicting_values=conflicting_values, source_modes=source_modes, resolution_state=CONFLICT_STATE, ) conflict_id = _domain_separated_sha256_hex_v01( domain=_CONFLICT_DOMAIN, payload=_canonical_json_bytes_v01(material), ) conflicts.append( ConflictSetV01( conflict_set_id=conflict_id, subject=subject, predicate=predicate, claim_ids=claim_ids, conflicting_values=conflicting_values, source_modes=source_modes, resolution_state=CONFLICT_STATE, ) ) return tuple(conflicts)
