@dataclass(frozen=True) class WorkOutputBindingV01: predecessor_work_id: str output_field: str expected_type: str
@dataclass(frozen=True) class WorkHistoricalOutputV01: task_id: str revision_id: str predecessor_work_id: str invocation_id: str result_id: str admission_id: str result_artifact_ref: str output_field: str expected_type: str value: action.ActionEffectParameterRecordV01
@dataclass(frozen=True) class WorkRevisionTriggerV01: trigger_id: str output: WorkHistoricalOutputV01
@dataclass(frozen=True) class WorkContinuationContextV01: host: hosts.RootWorkExecutionHostV01 snapshot: hosts.WorkTaskSnapshotV01 trigger: WorkRevisionTriggerV01 | pure.PureMissingNeedTriggerV01 | None = None
@dataclass(frozen=True) class WorkInputBindingV01: input_field: str source: WorkLiteralV01 | WorkOutputBindingV01 | WorkHistoricalOutputV01
@dataclass(frozen=True) class WorkBudgetV01: max_items: int max_children: int max_model_calls: int max_compute_units: int max_revisions: int
@dataclass(frozen=True) class WorkItemV01: work_id: str definition_id: str owning_root_id: str inputs: tuple[WorkInputBindingV01, ...] resource_refs: tuple[str, ...] depends_on: tuple[str, ...] guard: WorkOutputBindingV01 | None review_obligation_id: str | None
@dataclass(frozen=True) class WorkProgramCandidateV01: task_id: str revision_id: str previous_revision_id: str | None intent_ref: str bsep_ref: str semantic_proposal_ref: str catalogue_revision: int budget: WorkBudgetV01 items: tuple[WorkItemV01, ...] trigger_evidence_refs: tuple[str, ...]
@dataclass(frozen=True) class MaterializedWorkProgramV01: candidate: WorkProgramCandidateV01 topology_artifact: abi.KernelArtifactV01 ordered_work_ids: tuple[str, ...] source_bindings: tuple[abi.CausalConsumptionRefV01, ...]
@dataclass(frozen=True) class WorkItemResultV01: task_id: str revision_id: str work_id: str status: str invocation: firewall.BoundCapabilityInvocationV01 | None result: firewall.CapabilityExecutionResultV01 | None consumed_fields: tuple[abi.CausalConsumptionRefV01, ...] reasons: tuple[str, ...]
@dataclass(frozen=True) class WorkReviewObligationV01: obligation_id: str task_id: str revision_id: str work_id: str owning_root_id: str business_request_ref: str bsep_ref: str semantic_proposal_ref: str source_context: router.ExecutionModeSourceContextV01 router_input: router.ExecutionModeRouterInputV01 route_eligibility_artifact: abi.KernelArtifactV01 root_route_review: router.RootExecutionModeDecisionV01
def _require(ok, reason): if not ok: raise ValueError(reason)
def _text(value): return type(value) is str and action.validate_identity_text_v01(value)[0]
def _plain(value): if value is None or type(value) in (str, int, bool): return value if type(value) is tuple: return [_plain(v) for v in value] if type(value) is abi.KernelArtifactV01: return abi.kernel_artifact_to_plain_dict_v01(value) _require(type(value) in (WorkLiteralV01, WorkOutputBindingV01, WorkHistoricalOutputV01, WorkRevisionTriggerV01, WorkInputBindingV01, WorkBudgetV01, WorkItemV01, WorkProgramCandidateV01, WorkItemResultV01, hosts.WorkTaskPolicyV01, hosts.WorkTaskUsageV01, hosts.WorkTaskSnapshotV01, WorkTaskPendingActionV01, abi.CausalConsumptionRefV01, firewall.BoundCapabilityInvocationV01, firewall.CapabilityExecutionResultV01, firewall.CapabilityValidationEvidenceV01, action.ActionEffectParameterRecordV01), 'work_plain_type') return {f.name: _plain(getattr(value, f.name)) for f in fields(value)}
def _identity(leaf, value): return action.build_domain_separated_identity_v01(domain='hedgehog.common_action.' + leaf + '.v01', prefix=leaf + ':', material=(('payload', json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=True)),))
def _revision(candidate): value = _plain(candidate) del value['revision_id'] return _identity('work_revision', value)
def _payload(value, kind): schema = json.loads((Path(__file__).resolve().parents[2] / 'schemas/work_composition_v01.schema.json').read_text()) schema['$ref'] = '#/$defs/' + kind jsonschema.Draft202012Validator(schema).validate(value) return value
def _catalogue(catalogue): _require(type(catalogue) is tuple, 'work_catalogue_type') out = {} for admitted in catalogue: snapshot = firewall.snapshot_admitted_capability_v01(admitted) _require(snapshot.definition.definition_id not in out, 'work_duplicate_definition') out[snapshot.definition.definition_id] = admitted return out
def _order(items): remaining = {i.work_id: set(i.depends_on) for i in items} done = [] while remaining: ready = sorted(k for k, parents in remaining.items() if parents <= set(done)) _require(bool(ready), 'work_cycle') node = ready[0] done.append(node) del remaining[node] return tuple(done)
def _context(candidate, source_context, semantic_proposal): _require(type(source_context) is router.ExecutionModeSourceContextV01, 'work_context_type') _require(type(semantic_proposal) is abi.KernelArtifactV01 and not abi.validate_kernel_artifact_v01(semantic_proposal), 'work_semantic_artifact') _require((semantic_proposal.artifact_type, semantic_proposal.authority_class, semantic_proposal.lifecycle_state) == ('SemanticArchitectProposal', 'ADVISORY', 'PROPOSED'), 'work_semantic_authority') _require(candidate.semantic_proposal_ref == semantic_proposal.artifact_id and candidate.bsep_ref == source_context.bsep_packet['packet_id'] and candidate.intent_ref in semantic_proposal.trace_refs and candidate.bsep_ref in semantic_proposal.parent_refs, 'work_semantic_binding') router.build_execution_mode_bsep_binding_v01(request_id=candidate.task_id, transaction_id=semantic_proposal.transaction_id, owning_root_id=semantic_proposal.owner_root_id, domain_id=source_context.business_request_context_packet['domain'], source_context=source_context)
def validate_work_program_candidate_v01(candidate, *, catalogue, source_context, semantic_proposal, continuation_context=None): try: _require(type(candidate) is WorkProgramCandidateV01, 'work_candidate_type') _require(all(_text(getattr(candidate, n)) for n in ('task_id', 'revision_id', 'intent_ref', 'bsep_ref', 'semantic_proposal_ref')), 'work_identity') if continuation_context is None: _require(candidate.previous_revision_id is None, 'work_continuation_context_required') else: _validate_continuation_candidate(candidate, continuation_context, catalogue, source_context, semantic_proposal) _require(type(candidate.catalogue_revision) is int and candidate.catalogue_revision >= 0, 'work_catalogue_revision') budget = candidate.budget _require(type(budget) is WorkBudgetV01 and all(type(getattr(budget, f.name)) is int and 0 <= getattr(budget, f.name) <= 4096 for f in fields(budget)), 'work_budget_type') _require(type(candidate.items) is tuple and 0 < len(candidate.items) <= budget.max_items <= 256 and len(candidate.items) <= budget.max_compute_units and budget.max_model_calls == 0, 'work_budget_exhausted') _require(type(candidate.trigger_evidence_refs) is tuple and all(_text(r) for r in candidate.trigger_evidence_refs) and len(set(candidate.trigger_evidence_refs)) == len(candidate.trigger_evidence_refs), 'work_trigger_refs') definitions = _catalogue(catalogue) if continuation_context is not None and continuation_context.host._pure_permissions: _validate_task_catalogue(candidate, continuation_context.host, catalogue) else: _require(all(a.catalogue_revision == candidate.catalogue_revision for a in catalogue), 'work_catalogue_revision') _require(all(type(i) is WorkItemV01 for i in candidate.items), 'work_item_type') items = {i.work_id: i for i in candidate.items} _require(len(items) == len(candidate.items), 'work_duplicate_id') for item in candidate.items: _require(all(_text(getattr(item, n)) for n in ('work_id', 'definition_id', 'owning_root_id')), 'work_item_identity') _require(type(item.inputs) is tuple and all(type(b) is WorkInputBindingV01 for b in item.inputs), 'work_inputs_type') _require(type(item.depends_on) is tuple and len(set(item.depends_on)) == len(item.depends_on) and all(p in items and p != item.work_id for p in item.depends_on), 'work_unknown_edge') _require(type(item.resource_refs) is tuple and all(_text(r) for r in item.resource_refs) and tuple(sorted(set(item.resource_refs))) == item.resource_refs, 'work_resource_scope') _require(item.review_obligation_id is None or _text(item.review_obligation_id), 'work_review_id') bindings = list(item.inputs) if item.guard is not None: _require(type(item.guard) is WorkOutputBindingV01 and item.guard.expected_type == 'BOOLEAN', 'work_guard_type') bindings.append(WorkInputBindingV01('guard', item.guard)) for binding in bindings: _require(_text(binding.input_field), 'work_input_name') source = binding.source if type(source) is WorkLiteralV01: _require(action.validate_action_effect_parameter_record_v01(source.value)[0], 'work_literal_value') _require(source.value.parameter_name == binding.input_field, 'work_literal_name') else: if type(source) is WorkHistoricalOutputV01: _require(continuation_context is not None, 'work_historical_context_required') _require(source.task_id == candidate.task_id, 'work_historical_foreign_task') _historical_value(continuation_context.host, source, item, definitions) continue _require(type(source) is WorkOutputBindingV01, 'work_binding_type') _require(source.predecessor_work_id in item.depends_on, 'work_undeclared_input_edge') _require(_text(source.output_field) and _text(source.expected_type), 'work_output_binding') producer = items[source.predecessor_work_id] _require(producer.owning_root_id == item.owning_root_id, 'work_foreign_root_input') if producer.definition_id in definitions: fields_by_name = {f.name: f for f in definitions[producer.definition_id].definition.output_fields} _require(source.output_field in fields_by_name and fields_by_name[source.output_field].value_type == source.expected_type, 'work_output_contract') if item.definition_id in definitions: definition = definitions[item.definition_id].definition _require(item.resource_refs == definition.resource_refs, 'work_resource_scope') declared = {f.name: f for f in definition.input_fields} names = tuple(b.input_field for b in item.inputs) _require(len(set(names)) == len(names) and set(names) <= set(declared) and {f.name for f in definition.input_fields if f.required} <= set(names), 'work_input_contract') for binding in item.inputs: actual_type = binding.source.value.value_type if type(binding.source) is WorkLiteralV01 else binding.source.expected_type _require(actual_type == declared[binding.input_field].value_type, 'work_input_contract_type') _order(candidate.items) _context(candidate, source_context, semantic_proposal) _require(candidate.revision_id == _revision(candidate), 'work_revision_identity') _payload(_plain(candidate), 'program') return True, () except (ValueError, TypeError, KeyError, AttributeError, jsonschema.ValidationError) as exc: return False, (str(exc) if type(exc) is ValueError else 'work_candidate_shape',)
def build_work_program_candidate_v01(*, task_id, previous_revision_id, intent_ref, bsep_ref, semantic_proposal_ref, catalogue_revision, budget, items, trigger_evidence_refs, catalogue, source_context, semantic_proposal, continuation_context=None): candidate = WorkProgramCandidateV01(task_id, '', previous_revision_id, intent_ref, bsep_ref, semantic_proposal_ref, catalogue_revision, budget, items, trigger_evidence_refs) candidate = replace(candidate, revision_id=_revision(candidate)) ok, reasons = validate_work_program_candidate_v01(candidate, catalogue=catalogue, source_context=source_context, semantic_proposal=semantic_proposal, continuation_context=continuation_context) _require(ok, reasons[0] if reasons else 'work_invalid') return candidate
def work_program_candidate_to_artifact_v01(candidate, *, catalogue, source_context, semantic_proposal, continuation_context=None): ok, reasons = validate_work_program_candidate_v01(candidate, catalogue=catalogue, source_context=source_context, semantic_proposal=semantic_proposal, continuation_context=continuation_context) _require(ok, reasons[0] if reasons else 'work_invalid') payload = _payload({'work_program': _plain(candidate)}, 'proposal_payload') return abi.build_kernel_artifact_v01(abi_version='v1.0', artifact_id=_identity('work_proposal', payload), artifact_type='SemanticArchitectProposal', schema_version='v1', transaction_id=semantic_proposal.transaction_id, owner_root_id=semantic_proposal.owner_root_id, source_component='semantic_architect', authority_class='ADVISORY', lifecycle_state='PROPOSED', payload=payload, trace_refs=(candidate.task_id, candidate.revision_id), parent_refs=(semantic_proposal.artifact_id,), time_envelope=abi.kernel_artifact_to_plain_dict_v01(semantic_proposal)['time_envelope'])
def materialize_work_program_v01(candidate, *, catalogue, source_context, semantic_proposal, continuation_context=None): proposal = work_program_candidate_to_artifact_v01(candidate, catalogue=catalogue, source_context=source_context, semantic_proposal=semantic_proposal, continuation_context=continuation_context) ordered = _order(candidate.items) payload = _payload({'work_program': _plain(candidate), 'ordered_work_ids': list(ordered)}, 'topology_payload') source = abi.kernel_artifact_to_plain_dict_v01(semantic_proposal) topology = abi.build_kernel_artifact_v01(abi_version='v1.0', artifact_id=_identity('work_topology', payload), artifact_type='RuntimeExecutionTopology', schema_version='v1', transaction_id=semantic_proposal.transaction_id, owner_root_id=semantic_proposal.owner_root_id, source_component='runtime', authority_class='NON_AUTHORITY', lifecycle_state='VALIDATED', payload=payload, trace_refs=(candidate.task_id, candidate.revision_id), parent_refs=(proposal.artifact_id,), time_envelope=source['time_envelope']) bindings = tuple(abi.build_causal_consumption_ref_v01(producer_actor_id='semantic_architect', source_artifact_id=proposal.artifact_id, output_field='/work_program/' + field, consumer_component='work_composition', downstream_artifact_id=topology.artifact_id, decision_effect='materialize_work', disposition='USED', reason_code='used:validated_program_' + field, trace_refs=(candidate.task_id, candidate.revision_id)) for field in ('items', 'budget', 'bsep_ref')) return MaterializedWorkProgramV01(candidate, topology, ordered, bindings)
def _work_ref(candidate, item): return _identity('work_instance', [candidate.task_id, candidate.revision_id, item.work_id])
def _consume(candidate, item, binding, prior, definitions, host_map): if type(binding) is WorkHistoricalOutputV01: _require(binding.task_id == candidate.task_id, 'work_historical_foreign_task') host = host_map[item.owning_root_id] value = _historical_value(host, binding, item, definitions) ref = abi.build_causal_consumption_ref_v01(producer_actor_id=binding.predecessor_work_id, source_artifact_id=binding.result_id, output_field='/' + binding.output_field.replace('~', '~0').replace('/', '~1'), consumer_component='work_composition', downstream_artifact_id=_work_ref(candidate, item), decision_effect='bind_input', disposition='USED', reason_code='used:actual_historical_output_field', trace_refs=(candidate.task_id, candidate.revision_id, binding.revision_id, binding.invocation_id, binding.result_artifact_ref)) return value, ref producer = next(i for i in candidate.items if i.work_id == binding.predecessor_work_id) _require(producer.work_id in prior, 'work_missing_producer') previous = prior[producer.work_id] _require(previous.status == 'COMPLETED', 'work_producer_not_completed') _validate_completed(candidate, producer, previous, definitions, host_map) outputs = {v.parameter_name: v for v in previous.result.output} _require(binding.output_field in outputs, 'work_missing_output_field') value = outputs[binding.output_field] _require(value.value_type == binding.expected_type, 'work_output_type') ref = abi.build_causal_consumption_ref_v01(producer_actor_id=producer.work_id, source_artifact_id=previous.result.result_id, output_field='/' + binding.output_field.replace('~', '~0').replace('/', '~1'), consumer_component='work_composition', downstream_artifact_id=_work_ref(candidate, item), decision_effect='bind_input', disposition='USED', reason_code='used:actual_output_field', trace_refs=(candidate.task_id, candidate.revision_id, previous.invocation.invocation_id, item.work_id)) return value, ref
def _validate_completed(candidate, item, value, definitions, host_map): _require(type(value) is WorkItemResultV01 and (value.task_id, value.revision_id, value.work_id) == (candidate.task_id, candidate.revision_id, item.work_id), 'work_result_context') _require(value.status == 'COMPLETED' and value.reasons == (), 'work_result_not_complete') admitted = definitions[item.definition_id] snapshot = firewall.snapshot_admitted_capability_v01(admitted) _require(not firewall.validate_capability_execution_result_v01(value.result, value.invocation, snapshot), 'work_result_validation') _require(value.result.outcome == 'SUCCEEDED' and value.invocation.owning_root_id == item.owning_root_id and value.invocation.task_id == candidate.task_id, 'work_result_root_task') host = host_map[item.owning_root_id] _require(type(host) is hosts.RootWorkExecutionHostV01 and host.owning_root_id == item.owning_root_id and any((value.invocation, value.result) == pair for pair in host.completed_work), 'work_result_not_observed') _require(value.invocation.work_instance_id == _work_ref(candidate, item), 'work_result_instance')
def _inputs(candidate, item, prior, definitions, host_map): values, refs = [], [] for binding in item.inputs: if type(binding.source) is WorkLiteralV01: value = binding.source.value else: value, ref = _consume(candidate, item, binding.source, prior, definitions, host_map) refs.append(ref) values.append(action.build_action_effect_parameter_record_v01(parameter_name=binding.input_field, value_type=value.value_type, value=value.value)) return tuple(sorted(values, key=lambda v: v.parameter_name)), tuple(refs)
def _reviews(bindings): _require(type(bindings) is tuple and all(type(b) is tuple and len(b) == 3 and type(b[0]) is WorkReviewObligationV01 for b in bindings), 'work_review_bindings_shape') result = {o.obligation_id: (o, s, b) for o, s, b in bindings} _require(len(result) == len(bindings), 'work_duplicate_review') return result
def _review(candidate, item, reviews, semantic_proposal): if item.review_obligation_id is not None: _require(item.review_obligation_id in reviews, 'work_required_review_missing') obligation, source, bundle = reviews[item.review_obligation_id] ok, reasons = validate_work_review_binding_v01(obligation, candidate=candidate, item=item, source_context=source, execution_bundle=bundle, semantic_proposal=semantic_proposal) _require(ok, reasons[0] if reasons else 'work_review_invalid')
def _readiness(candidate, item, prior, definitions, host_map, reviews, semantic_proposal): if item.definition_id not in definitions: return 'NEEDS_CAPABILITY', 'work_unknown_capability', (), () if any(p not in prior or prior[p].status not in ('COMPLETED', 'SKIPPED_GUARD_FALSE') for p in item.depends_on): return 'BLOCKED_REQUIRED_OUTPUT', 'work_required_parent', (), () try: host = host_map[item.owning_root_id] _require(type(host) is hosts.RootWorkExecutionHostV01 and host.owning_root_id == item.owning_root_id, 'work_host_root') _require(any(definitions[item.definition_id] is a for a in host.admitted_catalogue), 'work_host_admission') values, refs = _inputs(candidate, item, prior, definitions, host_map) if item.guard is not None: guard, ref = _consume(candidate, item, item.guard, prior, definitions, host_map) _require(guard.value_type == 'BOOLEAN' and type(guard.value) is bool, 'work_guard_type') if guard.value is False: return 'SKIPPED_GUARD_FALSE', 'work_guard_false', (), (ref,) refs += (ref,) _review(candidate, item, reviews, semantic_proposal) return 'READY', 'work_root_action_required', values, refs except (ValueError, KeyError) as exc: return 'BLOCKED_INVALID_INPUT', str(exc) if type(exc) is ValueError else 'work_binding_missing', (), ()
def _attempts(candidate, item, host_map): host = host_map.get(item.owning_root_id) if type(host) is not hosts.RootWorkExecutionHostV01: return () return tuple(a for a in host.work_attempts if a.task_id == candidate.task_id and a.work_instance_id == _work_ref(candidate, item))
def validate_work_program_result_v01(program, results, *, catalogue, host_map, source_context, semantic_proposal, review_bindings=(), continuation_context=None): try: _require(type(program) is MaterializedWorkProgramV01 and type(results) is tuple, 'work_results_type') candidate = program.candidate _require(program == materialize_work_program_v01(candidate, catalogue=catalogue, source_context=source_context, semantic_proposal=semantic_proposal, continuation_context=continuation_context), 'work_materialization_binding') reviews = _reviews(review_bindings) _require(all(s.g2c_source_context == source_context and o.router_input.transaction_id == semantic_proposal.transaction_id for o, s, _ in reviews.values()), 'work_review_program_context') definitions = _catalogue(catalogue) items = {i.work_id: i for i in candidate.items} previous = {} positions = [] for value in results: _require(type(value) is WorkItemResultV01 and value.work_id in items and value.work_id not in previous, 'work_result_key') item = items[value.work_id] _require((value.task_id, value.revision_id) == (candidate.task_id, candidate.revision_id), 'work_result_context') _require(type(value.consumed_fields) is tuple and all(not abi.validate_causal_consumption_ref_v01(r) for r in value.consumed_fields), 'work_consumption_shape') if value.status == 'COMPLETED': _review(candidate, item, reviews, semantic_proposal) _validate_completed(candidate, item, value, definitions, host_map) _require(all(p in previous and previous[p].status in ('COMPLETED', 'SKIPPED_GUARD_FALSE') for p in item.depends_on), 'work_required_parent') inputs, refs = _inputs(candidate, item, previous, definitions, host_map) if item.guard is not None: guard, ref = _consume(candidate, item, item.guard, previous, definitions, host_map) _require(guard.value_type == 'BOOLEAN' and guard.value is True, 'work_guard_not_true') refs += (ref,) _require(inputs == value.invocation.inputs and refs == value.consumed_fields, 'work_consumed_input_binding') elif 