def _source_ref(source_context, semantic_proposal): from collections.abc import Mapping from dataclasses import is_dataclass
def plain(value): if value is None or type(value) in (str, int, bool, float): return value if isinstance(value, Mapping): return {k: plain(v) for k, v in value.items()} if type(value) in (tuple, list): return [plain(v) for v in value] _require(is_dataclass(value), 'work_task_source_shape') return {f.name: plain(getattr(value, f.name)) for f in fields(value)}
material = plain(source_context) # Without a G2-A packet these are downstream routing-observation coordinates, # not original business/BSEP authority. Actual review validates its own view. if source_context.g2a_registry is None: for name in ('g2a_evaluation_time', 'g2a_evaluation_time_source', 'g2a_evaluation_context_id'): material.pop(name, None) return _identity('work_task_source', [material, _plain(semantic_proposal)])
